update shams_private.quiz_bank set payload='{"id":"prophets-01","category":"prophets","difficulty":1,"question":{"az":"Dənizdə quru yol açmaq üçün əsasını vurmaq əmri hansı peyğəmbərə verildi?","tr":"Denizde kuru yol açma emrini hangi peygamber aldı?","ru":"Какому пророку велено проложить сухой путь через море?","en":"Which prophet was told to make a dry passage through the sea?","ar":"أي نبي أُمر بشق طريق يابس في البحر؟"},"options":[{"az":"Davud","tr":"Davud","ru":"Дауд","en":"Dawud (David)","ar":"داود"},{"az":"Adəm","tr":"Âdem","ru":"Адам","en":"Adam","ar":"آدم"},{"az":"Musa","tr":"Musa","ru":"Муса","en":"Musa (Moses)","ar":"موسى"},{"az":"Yusif","tr":"Yusuf","ru":"Юсуф","en":"Yusuf (Joseph)","ar":"يوسف"}],"correct":2,"explanation":{"az":"Taha 20:77-də Musa bu əmri alır.","tr":"Taha 20:77’de Musa bu emri alır.","ru":"В Таха 20:77 это повеление дано Мусе.","en":"Taha 20:77 gives this command to Musa.","ar":"ورد هذا الأمر لموسى في طه ٢٠:٧٧."},"source_reference":"Quran 20:77","source_url":"https://quran.com/20/77","reviewed":true,"active":true,"topic":"prophets","tier":1,"concept_id":"prophets-01","option_ids":["prophets-01:0","prophets-01:1","prophets-01:2","prophets-01:3"],"correct_option_id":"prophets-01:2","review_status":"legacy-reviewed"}'::jsonb where id='prophets-01';
update shams_private.quiz_bank set payload='{"id":"prophets-02","category":"prophets","difficulty":1,"question":{"az":"Allah hansı peyğəmbərə gəmi düzəltməyi əmr etdi?","tr":"Gemi yapma emri hangi peygambere verildi?","ru":"Какому пророку было велено построить ковчег?","en":"Which prophet was commanded to build the Ark?","ar":"أي نبي أُمر بصنع الفلك؟"},"options":[{"az":"Yəhya","tr":"Yahya","ru":"Яхья","en":"Yahya (John)","ar":"يحيى"},{"az":"Nuh","tr":"Nuh","ru":"Нух","en":"Nuh (Noah)","ar":"نوح"},{"az":"Musa","tr":"Musa","ru":"Муса","en":"Musa (Moses)","ar":"موسى"},{"az":"İsa","tr":"İsa","ru":"Иса","en":"Isa (Jesus)","ar":"عيسى"}],"correct":1,"explanation":{"az":"Hud 11:36–37 Nuhun gəmisindən bəhs edir.","tr":"Hud 11:36–37 Nuh’un gemisini anlatır.","ru":"Худ 11:36–37 рассказывает о ковчеге Нуха.","en":"Hud 11:36–37 describes Nuh’s Ark.","ar":"تتحدث هود ١١:٣٦–٣٧ عن فلك نوح."},"source_reference":"Quran 11:37","source_url":"https://quran.com/11/37","reviewed":true,"active":true,"topic":"prophets","tier":1,"concept_id":"prophets-02","option_ids":["prophets-02:0","prophets-02:1","prophets-02:2","prophets-02:3"],"correct_option_id":"prophets-02:1","review_status":"legacy-reviewed"}'::jsonb where id='prophets-02';
update shams_private.quiz_bank set payload='{"id":"prophets-03","category":"prophets","difficulty":1,"question":{"az":"Quranda balığın udduğu peyğəmbər kimi kim xatırlanır?","tr":"Kur’an’daki balık tarafından yutulma kıssası hangi peygamberle ilgilidir?","ru":"С каким пророком связана история о большой рыбе?","en":"Which prophet is associated with being swallowed by a great fish?","ar":"أي نبي تتعلق به قصة ابتلاع الحوت؟"},"options":[{"az":"Yunus","tr":"Yunus","ru":"Юнус","en":"Yunus (Jonah)","ar":"يونس"},{"az":"Hud","tr":"Hud","ru":"Худ","en":"Hud","ar":"هود"},{"az":"Saleh","tr":"Salih","ru":"Салих","en":"Salih","ar":"صالح"},{"az":"İsmayıl","tr":"İsmail","ru":"Исмаил","en":"Ismail (Ishmael)","ar":"إسماعيل"}],"correct":0,"explanation":{"az":"Saffat 37:139–142 Yunusun hekayəsini danışır.","tr":"Saffat 37:139–142 Yunus’un kıssasını anlatır.","ru":"Ас-Саффат 37:139–142 рассказывает о Юнусе.","en":"As-Saffat 37:139–142 recounts Yunus’s story.","ar":"تروي الصافات ٣٧:١٣٩–١٤٢ قصة يونس."},"source_reference":"Quran 37:142","source_url":"https://quran.com/37/142","reviewed":true,"active":true,"topic":"prophets","tier":1,"concept_id":"prophets-03","option_ids":["prophets-03:0","prophets-03:1","prophets-03:2","prophets-03:3"],"correct_option_id":"prophets-03:0","review_status":"legacy-reviewed"}'::jsonb where id='prophets-03';
update shams_private.quiz_bank set payload='{"id":"prophets-04","category":"prophets","difficulty":1,"question":{"az":"Yuxuda on bir ulduzun, günəşin və ayın ona səcdə etdiyini hansı peyğəmbər görmüşdü?","tr":"Rüyasında on bir yıldız, güneş ve ayı gören kimdi?","ru":"Кто увидел во сне одиннадцать звёзд, солнце и луну?","en":"Who dreamt of eleven stars, the sun and the moon?","ar":"من رأى أحد عشر كوكباً والشمس والقمر في المنام؟"},"options":[{"az":"Süleyman","tr":"Süleyman","ru":"Сулейман","en":"Sulayman (Solomon)","ar":"سليمان"},{"az":"Nuh","tr":"Nuh","ru":"Нух","en":"Nuh (Noah)","ar":"نوح"},{"az":"Zəkəriyya","tr":"Zekeriya","ru":"Закария","en":"Zakariyya (Zechariah)","ar":"زكريا"},{"az":"Yusif","tr":"Yusuf","ru":"Юсуф","en":"Yusuf (Joseph)","ar":"يوسف"}],"correct":3,"explanation":{"az":"Yusif 12:4-də bu yuxunu atasına danışır.","tr":"Yusuf 12:4’te bu rüyayı babasına anlatır.","ru":"Юсуф рассказывает этот сон отцу в 12:4.","en":"Yusuf tells his father this dream in 12:4.","ar":"يحكي يوسف هذا المنام لأبيه في يوسف ١٢:٤."},"source_reference":"Quran 12:4","source_url":"https://quran.com/12/4","reviewed":true,"active":true,"topic":"prophets","tier":1,"concept_id":"prophets-04","option_ids":["prophets-04:0","prophets-04:1","prophets-04:2","prophets-04:3"],"correct_option_id":"prophets-04:3","review_status":"legacy-reviewed"}'::jsonb where id='prophets-04';
update shams_private.quiz_bank set payload='{"id":"prophets-05","category":"prophets","difficulty":1,"question":{"az":"İbrahim peyğəmbərlə birlikdə Kəbənin təməllərini kim ucaltdı?","tr":"Kâbe’nin temellerini İbrahim ile birlikte kim yükseltti?","ru":"Кто поднимал основания Каабы вместе с Ибрахимом?","en":"Who raised the House’s foundations with Ibrahim?","ar":"من رفع قواعد البيت مع إبراهيم؟"},"options":[{"az":"Yunus","tr":"Yunus","ru":"Юнус","en":"Yunus (Jonah)","ar":"يونس"},{"az":"Hud","tr":"Hud","ru":"Худ","en":"Hud","ar":"هود"},{"az":"İsmayıl","tr":"İsmail","ru":"Исмаил","en":"Ismail (Ishmael)","ar":"إسماعيل"},{"az":"Yəhya","tr":"Yahya","ru":"Яхья","en":"Yahya (John)","ar":"يحيى"}],"correct":2,"explanation":{"az":"Bəqərə 2:127 İbrahim və İsmayılı birlikdə qeyd edir.","tr":"Bakara 2:127 İbrahim ile İsmail’i birlikte anar.","ru":"Аль-Бакара 2:127 называет Ибрахима и Исмаила.","en":"Al-Baqarah 2:127 names Ibrahim and Ismail together.","ar":"تذكر البقرة ٢:١٢٧ إبراهيم وإسماعيل معاً."},"source_reference":"Quran 2:127","source_url":"https://quran.com/2/127","reviewed":true,"active":true,"topic":"prophets","tier":1,"concept_id":"prophets-05","option_ids":["prophets-05:0","prophets-05:1","prophets-05:2","prophets-05:3"],"correct_option_id":"prophets-05:2","review_status":"legacy-reviewed"}'::jsonb where id='prophets-05';
