update shams_private.quiz_bank set payload='{"id":"prophets-07","category":"prophets","difficulty":1,"question":{"az":"Quranda “Məryəm oğlu” kimi təqdim olunan peyğəmbər kimdir?","tr":"Kur’an’da “Meryem oğlu” denilen peygamber kimdir?","ru":"Какой пророк назван в Коране сыном Марьям?","en":"Which prophet is called the son of Maryam in the Quran?","ar":"أي نبي وصفه القرآن بابن مريم؟"},"options":[{"az":"İsa","tr":"İsa","ru":"Иса","en":"Isa (Jesus)","ar":"عيسى"},{"az":"Yəhya","tr":"Yahya","ru":"Яхья","en":"Yahya (John)","ar":"يحيى"},{"az":"Adəm","tr":"Âdem","ru":"Адам","en":"Adam","ar":"آدم"},{"az":"İsmayıl","tr":"İsmail","ru":"Исмаил","en":"Ismail (Ishmael)","ar":"إسماعيل"}],"correct":0,"explanation":{"az":"Məryəm 19:34-də İsa, Məryəm oğlu kimi göstərilir.","tr":"Meryem 19:34’te İsa, Meryem oğlu olarak anılır.","ru":"Марьям 19:34 называет Ису сыном Марьям.","en":"Maryam 19:34 identifies Isa as Maryam’s son.","ar":"تذكر مريم ١٩:٣٤ عيسى ابن مريم."},"source_reference":"Quran 19:34","source_url":"https://quran.com/19/34","reviewed":true,"active":true,"topic":"prophets","tier":1,"concept_id":"prophets-07","option_ids":["prophets-07:0","prophets-07:1","prophets-07:2","prophets-07:3"],"correct_option_id":"prophets-07:0","review_status":"legacy-reviewed"}'::jsonb where id='prophets-07';
update shams_private.quiz_bank set payload='{"id":"prophets-08","category":"prophets","difficulty":1,"question":{"az":"Allahın adları öyrətdiyi ilk insan və peyğəmbər kimdir?","tr":"Allah her şeyin isimlerini kime öğretti?","ru":"Кому Аллах научил именам всех вещей?","en":"Whom did Allah teach the names of all things?","ar":"من علّمه الله الأسماء كلها؟"},"options":[{"az":"Nuh","tr":"Nuh","ru":"Нух","en":"Nuh (Noah)","ar":"نوح"},{"az":"Yusif","tr":"Yusuf","ru":"Юсуф","en":"Yusuf (Joseph)","ar":"يوسف"},{"az":"Davud","tr":"Davud","ru":"Дауд","en":"Dawud (David)","ar":"داود"},{"az":"Adəm","tr":"Âdem","ru":"Адам","en":"Adam","ar":"آدم"}],"correct":3,"explanation":{"az":"Bəqərə 2:31-də adların Adəmə öyrədildiyi bildirilir.","tr":"Bakara 2:31’de isimlerin Âdem’e öğretildiği belirtilir.","ru":"Аль-Бакара 2:31 говорит об обучении Адама именам.","en":"Al-Baqarah 2:31 describes Adam being taught the names.","ar":"تخبر البقرة ٢:٣١ بتعليم آدم الأسماء."},"source_reference":"Quran 2:31","source_url":"https://quran.com/2/31","reviewed":true,"active":true,"topic":"prophets","tier":1,"concept_id":"prophets-08","option_ids":["prophets-08:0","prophets-08:1","prophets-08:2","prophets-08:3"],"correct_option_id":"prophets-08:3","review_status":"legacy-reviewed"}'::jsonb where id='prophets-08';
