update shams_private.quiz_bank set payload='{"id":"prophets-10","category":"prophets","difficulty":4,"question":{"az":"Zəkəriyya peyğəmbərə hansı adlı oğul müjdələndi?","tr":"Zekeriya’ya hangi isimde bir oğul müjdelendi?","ru":"О рождении сына с каким именем сообщили Закарии?","en":"What was the name of the son promised to Zakariyya?","ar":"ما اسم الغلام الذي بُشّر به زكريا؟"},"options":[{"az":"Davud","tr":"Davud","ru":"Дауд","en":"Dawud (David)","ar":"داود"},{"az":"Yəhya","tr":"Yahya","ru":"Яхья","en":"Yahya (John)","ar":"يحيى"},{"az":"İsmayıl","tr":"İsmail","ru":"Исмаил","en":"Ismail (Ishmael)","ar":"إسماعيل"},{"az":"Musa","tr":"Musa","ru":"Муса","en":"Musa (Moses)","ar":"موسى"}],"correct":1,"explanation":{"az":"Məryəm 19:7-də Yəhyanın adı açıq çəkilir.","tr":"Meryem 19:7’de Yahya’nın adı açıkça anılır.","ru":"В Марьям 19:7 прямо назван Яхья.","en":"Maryam 19:7 explicitly gives the name Yahya.","ar":"ورد اسم يحيى صريحاً في مريم ١٩:٧."},"source_reference":"Quran 19:7","source_url":"https://quran.com/19/7","reviewed":true,"active":true,"topic":"prophets","tier":3,"concept_id":"prophets-10","option_ids":["prophets-10:0","prophets-10:1","prophets-10:2","prophets-10:3"],"correct_option_id":"prophets-10:1","review_status":"legacy-reviewed"}'::jsonb where id='prophets-10';
update shams_private.quiz_bank set payload='{"id":"history-01","category":"history","difficulty":1,"question":{"az":"Ali-İmran surəsinin 123-cü ayəsində hansı döyüş xatırlanır?","tr":"Âl-i İmran 3:123’te hangi savaş anılır?","ru":"Какая битва названа в Аль-Имран 3:123?","en":"Which battle is named in Ali Imran 3:123?","ar":"ما المعركة المذكورة في آل عمران ٣:١٢٣؟"},"options":[{"az":"Bədr","tr":"Bedir","ru":"Бадр","en":"Badr","ar":"بدر"},{"az":"Xəndək","tr":"Hendek","ru":"Хандак","en":"The Trench","ar":"الخندق"},{"az":"Mütə","tr":"Mute","ru":"Мута","en":"Mutah","ar":"مؤتة"},{"az":"Yərmuk","tr":"Yermük","ru":"Ярмук","en":"Yarmuk","ar":"اليرموك"}],"correct":0,"explanation":{"az":"Ayə Bədrdə verilən köməyi xatırladır.","tr":"Ayet Bedir’de verilen yardımı hatırlatır.","ru":"Аят напоминает о помощи при Бадре.","en":"The verse recalls help granted at Badr.","ar":"تذكّر الآية بالنصر في بدر."},"source_reference":"Quran 3:123","source_url":"https://quran.com/3/123","reviewed":true,"active":true,"topic":"history","tier":1,"concept_id":"history-01","option_ids":["history-01:0","history-01:1","history-01:2","history-01:3"],"correct_option_id":"history-01:0","review_status":"legacy-reviewed"}'::jsonb where id='history-01';
update shams_private.quiz_bank set payload='{"id":"history-02","category":"history","difficulty":2,"question":{"az":"Tövbə surəsinin 25-ci ayəsində müsəlmanların say çoxluğuna güvəndiyi hansı döyüş xatırlanır?","tr":"Tevbe 9:25’te çokluğa güvenilen hangi gün anılır?","ru":"Какой день чрезмерной уверенности в численности назван в 9:25?","en":"Which battle day, when numbers inspired pride, is recalled in 9:25?","ar":"أي يوم ذُكر في التوبة ٩:٢٥ حين أعجبت المؤمنين كثرتهم؟"},"options":[{"az":"Bədr","tr":"Bedir","ru":"Бадр","en":"Badr","ar":"بدر"},{"az":"Yərmuk","tr":"Yermük","ru":"Ярмук","en":"Yarmuk","ar":"اليرموك"},{"az":"Qadisiyyə","tr":"Kadisiye","ru":"Кадисия","en":"Qadisiyyah","ar":"القادسية"},{"az":"Hüneyn","tr":"Huneyn","ru":"Хунайн","en":"Hunayn","ar":"حنين"}],"correct":3,"explanation":{"az":"Ayədə Hüneyn günü açıq adlandırılır.","tr":"Ayette Huneyn günü açıkça adlandırılır.","ru":"Аят прямо называет день Хунайна.","en":"The verse explicitly names the day of Hunayn.","ar":"تسمّي الآية يوم حنين صراحة."},"source_reference":"Quran 9:25","source_url":"https://quran.com/9/25","reviewed":true,"active":true,"topic":"history","tier":2,"concept_id":"history-02","option_ids":["history-02:0","history-02:1","history-02:2","history-02:3"],"correct_option_id":"history-02:3","review_status":"legacy-reviewed"}'::jsonb where id='history-02';
update shams_private.quiz_bank set payload='{"id":"history-03","category":"history","difficulty":1,"question":{"az":"Əshabi-kəhf hekayəsində gənclər haraya sığınmışdılar?","tr":"Ashab-ı Kehf hangi mekânla ilişkilidir?","ru":"С каким убежищем связаны люди Аль-Кахф?","en":"What shelter is associated with the people of Al-Kahf?","ar":"بأي مأوى ارتبط أصحاب الكهف؟"},"options":[{"az":"Saray","tr":"Saray","ru":"Дворец","en":"A palace","ar":"قصر"},{"az":"Qala","tr":"Kale","ru":"Крепость","en":"A fortress","ar":"حصن"},{"az":"Mağara","tr":"Mağara","ru":"Пещера","en":"A cave","ar":"كهف"},{"az":"Gəmi","tr":"Gemi","ru":"Ковчег","en":"An ark","ar":"فلك"}],"correct":2,"explanation":{"az":"Kəhf 18:9 mağara əhlini xatırladır.","tr":"Kehf 18:9 mağara ehlini hatırlatır.","ru":"Аль-Кахф 18:9 упоминает людей пещеры.","en":"Al-Kahf 18:9 mentions the people of the cave.","ar":"تذكر الكهف ١٨:٩ أصحاب الكهف."},"source_reference":"Quran 18:9","source_url":"https://quran.com/18/9","reviewed":true,"active":true,"topic":"history","tier":1,"concept_id":"history-03","option_ids":["history-03:0","history-03:1","history-03:2","history-03:3"],"correct_option_id":"history-03:2","review_status":"legacy-reviewed"}'::jsonb where id='history-03';
update shams_private.quiz_bank set payload='{"id":"history-04","category":"history","difficulty":2,"question":{"az":"Qurana görə dağları yonaraq evlər tikən qövm hansıdır?","tr":"Dağları yontarak ev yapan kavim hangisidir?","ru":"Какой народ высекал дома в горах?","en":"Which people carved homes into mountains?","ar":"أي قوم نحتوا من الجبال بيوتاً؟"},"options":[{"az":"Səba","tr":"Sebe","ru":"Саба","en":"Saba","ar":"سبأ"},{"az":"Səmud","tr":"Semud","ru":"Самуд","en":"Thamud","ar":"ثمود"},{"az":"Mədyən","tr":"Medyen","ru":"Мадьян","en":"Madyan","ar":"مدين"},{"az":"Rum","tr":"Rum","ru":"Римляне","en":"The Romans","ar":"الروم"}],"correct":1,"explanation":{"az":"Əraf 7:73–74 bu təsviri Səmud hekayəsində verir.","tr":"Araf 7:73–74 bunu Semud kıssasında anlatır.","ru":"Аль-Араф 7:73–74 описывает это в рассказе о Самуде.","en":"Al-Araf 7:73–74 gives this detail in the Thamud account.","ar":"يَرِد هذا الوصف في قصة ثمود في الأعراف ٧:٧٣–٧٤."},"source_reference":"Quran 7:73-74","source_url":"https://quran.com/7/73-74","reviewed":true,"active":true,"topic":"history","tier":2,"concept_id":"history-04","option_ids":["history-04:0","history-04:1","history-04:2","history-04:3"],"correct_option_id":"history-04:1","review_status":"legacy-reviewed"}'::jsonb where id='history-04';
update shams_private.quiz_bank set payload='{"id":"history-05","category":"history","difficulty":1,"question":{"az":"Hud peyğəmbər hansı qövmə göndərilmişdi?","tr":"Âd kavmine hangi peygamber gönderildi?","ru":"Какой пророк был послан к народу Ад?","en":"Which prophet was sent to the people of Ad?","ar":"أي نبي أُرسل إلى عاد؟"},"options":[{"az":"Hud","tr":"Hud","ru":"Худ","en":"Hud","ar":"هود"},{"az":"Yəhya","tr":"Yahya","ru":"Яхья","en":"Yahya (John)","ar":"يحيى"},{"az":"Zəkəriyya","tr":"Zekeriya","ru":"Закария","en":"Zakariyya (Zechariah)","ar":"زكريا"},{"az":"İsa","tr":"İsa","ru":"Иса","en":"Isa (Jesus)","ar":"عيسى"}],"correct":0,"explanation":{"az":"Hud 11:50 Ad qövmü ilə Hudu əlaqələndirir.","tr":"Hud 11:50 Âd kavmiyle Hud’u ilişkilendirir.","ru":"Худ 11:50 называет Худа посланником к Ад.","en":"Hud 11:50 connects Hud with the people of Ad.","ar":"تذكر هود ١١:٥٠ إرسال هود إلى عاد."},"source_reference":"Quran 11:50","source_url":"https://quran.com/11/50","reviewed":true,"active":true,"topic":"history","tier":1,"concept_id":"history-05","option_ids":["history-05:0","history-05:1","history-05:2","history-05:3"],"correct_option_id":"history-05:0","review_status":"legacy-reviewed"}'::jsonb where id='history-05';
update shams_private.quiz_bank set payload='{"id":"history-06","category":"history","difficulty":2,"question":{"az":"Mədyən xalqına göndərilən peyğəmbər kim idi?","tr":"Medyen halkına gönderilen peygamber kimdir?","ru":"Какой пророк был послан к Мадьяну?","en":"Which prophet was sent to Madyan?","ar":"أي نبي أُرسل إلى مدين؟"},"options":[{"az":"Süleyman","tr":"Süleyman","ru":"Сулейман","en":"Sulayman (Solomon)","ar":"سليمان"},{"az":"İsmayıl","tr":"İsmail","ru":"Исмаил","en":"Ismail (Ishmael)","ar":"إسماعيل"},{"az":"Davud","tr":"Davud","ru":"Дауд","en":"Dawud (David)","ar":"داود"},{"az":"Şüeyb","tr":"Şuayb","ru":"Шуайб","en":"Shuayb","ar":"شعيب"}],"correct":3,"explanation":{"az":"Əraf 7:85-də Mədyən və Şüeyb birlikdə çəkilir.","tr":"Araf 7:85’te Medyen ve Şuayb birlikte anılır.","ru":"Аль-Араф 7:85 вместе упоминает Мадьян и Шуайба.","en":"Al-Araf 7:85 names Madyan and Shuayb together.","ar":"تذكر الأعراف ٧:٨٥ مدين وشعيباً معاً."},"source_reference":"Quran 7:85","source_url":"https://quran.com/7/85","reviewed":true,"active":true,"topic":"history","tier":2,"concept_id":"history-06","option_ids":["history-06:0","history-06:1","history-06:2","history-06:3"],"correct_option_id":"history-06:3","review_status":"legacy-reviewed"}'::jsonb where id='history-06';
update shams_private.quiz_bank set payload='{"id":"history-07","category":"history","difficulty":1,"question":{"az":"Musa peyğəmbərin Allahın əmri ilə qarşısına çıxdığı hökmdar kim idi?","tr":"Musa hangi hükümdara gönderilmişti?","ru":"К какому правителю был послан Муса?","en":"To which ruler was Musa sent?","ar":"إلى أي حاكم أُرسل موسى؟"},"options":[{"az":"Talut","tr":"Talut","ru":"Талут","en":"Talut","ar":"طالوت"},{"az":"Səba hökmdarı","tr":"Sebe hükümdarı","ru":"Правитель Сабы","en":"The ruler of Saba","ar":"حاكم سبأ"},{"az":"Firon","tr":"Firavun","ru":"Фараон","en":"Pharaoh","ar":"فرعون"},{"az":"Qarun","tr":"Karun","ru":"Карун","en":"Qarun","ar":"قارون"}],"correct":2,"explanation":{"az":"Əraf 7:103 Musanın Firona göndərilməsini bildirir.","tr":"Araf 7:103 Musa’nın Firavun’a gönderildiğini bildirir.","ru":"Аль-Араф 7:103 сообщает о послании Мусы к Фараону.","en":"Al-Araf 7:103 states that Musa was sent to Pharaoh.","ar":"تذكر الأعراف ٧:١٠٣ بعثة موسى إلى فرعون."},"source_reference":"Quran 7:103","source_url":"https://quran.com/7/103","reviewed":true,"active":true,"topic":"history","tier":1,"concept_id":"history-07","option_ids":["history-07:0","history-07:1","history-07:2","history-07:3"],"correct_option_id":"history-07:2","review_status":"legacy-reviewed"}'::jsonb where id='history-07';
update shams_private.quiz_bank set payload='{"id":"history-08","category":"history","difficulty":3,"question":{"az":"Qarun hansı peyğəmbərin qövmündən idi?","tr":"Karun hangi peygamberin kavmindendi?","ru":"Из народа какого пророка происходил Карун?","en":"Qarun belonged to which prophet’s people?","ar":"من قوم أي نبي كان قارون؟"},"options":[{"az":"Hud","tr":"Hud","ru":"Худ","en":"Hud","ar":"هود"},{"az":"Musa","tr":"Musa","ru":"Муса","en":"Musa (Moses)","ar":"موسى"},{"az":"Nuh","tr":"Nuh","ru":"Нух","en":"Nuh (Noah)","ar":"نوح"},{"az":"Yunus","tr":"Yunus","ru":"Юнус","en":"Yunus (Jonah)","ar":"يونس"}],"correct":1,"explanation":{"az":"Qəsəs 28:76 Qarunun Musa qövmündən olduğunu deyir.","tr":"Kasas 28:76 Karun’un Musa’nın kavminden olduğunu söyler.","ru":"Аль-Касас 28:76 относит Каруна к народу Мусы.","en":"Al-Qasas 28:76 identifies Qarun with Musa’s people.","ar":"تذكر القصص ٢٨:٧٦ أن قارون كان من قوم موسى."},"source_reference":"Quran 28:76","source_url":"https://quran.com/28/76","reviewed":true,"active":true,"topic":"history","tier":3,"concept_id":"history-08","option_ids":["history-08:0","history-08:1","history-08:2","history-08:3"],"correct_option_id":"history-08:1","review_status":"legacy-reviewed"}'::jsonb where id='history-08';
update shams_private.quiz_bank set payload='{"id":"history-09","category":"history","difficulty":3,"question":{"az":"Quranda oğluna Allaha şərik qoşmamağı tövsiyə edən şəxs kimdir?","tr":"Oğluna Allah’a ortak koşmamayı öğütleyen kimdi?","ru":"Кто наставлял сына не приобщать Аллаху сотоварищей?","en":"Who advised his son not to associate partners with Allah in 31:13?","ar":"من وعظ ابنه بألّا يشرك بالله في لقمان ٣١:١٣؟"},"options":[{"az":"Loğman","tr":"Lokman","ru":"Лукман","en":"Luqman","ar":"لقمان"},{"az":"Saleh","tr":"Salih","ru":"Салих","en":"Salih","ar":"صالح"},{"az":"Yəhya","tr":"Yahya","ru":"Яхья","en":"Yahya (John)","ar":"يحيى"},{"az":"İsmayıl","tr":"İsmail","ru":"Исмаил","en":"Ismail (Ishmael)","ar":"إسماعيل"}],"correct":0,"explanation":{"az":"Loğman 31:13-də bu nəsihəti oğluna verir.","tr":"Lokman 31:13’te bu öğüdü oğluna verir.","ru":"Лукман даёт сыну это наставление в 31:13.","en":"Luqman gives this advice to his son in 31:13.","ar":"يوصي لقمان ابنه بهذا في لقمان ٣١:١٣."},"source_reference":"Quran 31:13","source_url":"https://quran.com/31/13","reviewed":true,"active":true,"topic":"history","tier":3,"concept_id":"history-09","option_ids":["history-09:0","history-09:1","history-09:2","history-09:3"],"correct_option_id":"history-09:0","review_status":"legacy-reviewed"}'::jsonb where id='history-09';
update shams_private.quiz_bank set payload='{"id":"history-10","category":"history","difficulty":4,"question":{"az":"Rum surəsinin ilk ayələrində hansı xalqın məğlubiyyətindən bəhs olunur?","tr":"Rum suresinin başında yenilgisi anılan halk hangisidir?","ru":"Чьё поражение упомянуто в начале суры Ар-Рум?","en":"Whose defeat is mentioned at the opening of Ar-Rum?","ar":"من ذُكرت هزيمتهم في أول سورة الروم؟"},"options":[{"az":"Səmud","tr":"Semud","ru":"Самуд","en":"Thamud","ar":"ثمود"},{"az":"Ad","tr":"Âd","ru":"Ад","en":"Ad","ar":"عاد"},{"az":"Mədyən","tr":"Medyen","ru":"Мадьян","en":"Madyan","ar":"مدين"},{"az":"Rumlular","tr":"Romalılar","ru":"Римляне","en":"The Romans","ar":"الروم"}],"correct":3,"explanation":{"az":"Rum 30:2–3 rumluların məğlubiyyətini xatırladır.","tr":"Rum 30:2–3 Romalıların yenilgisini hatırlatır.","ru":"Ар-Рум 30:2–3 говорит о поражении римлян.","en":"Ar-Rum 30:2–3 recalls the Romans’ defeat.","ar":"تذكر الروم ٣٠:٢–٣ هزيمة الروم."},"source_reference":"Quran 30:2-3","source_url":"https://quran.com/30/2-3","reviewed":true,"active":true,"topic":"history","tier":3,"concept_id":"history-10","option_ids":["history-10:0","history-10:1","history-10:2","history-10:3"],"correct_option_id":"history-10:3","review_status":"legacy-reviewed"}'::jsonb where id='history-10';
update shams_private.quiz_bank set payload='{"id":"prayer-01","category":"prayer","difficulty":1,"question":{"az":"Quranda müsəlmanlara namazda üzlərini hansı məscidə tərəf çevirmək buyurulur?","tr":"Namazda yönelmek için Kur’an’da hangi mescit gösterilir?","ru":"К какой мечети Коран велит обращаться при молитве?","en":"Which mosque does the Quran name as the direction of prayer?","ar":"أي مسجد يذكره القرآن جهةً للصلاة؟"},"options":[{"az":"Quba məscidi","tr":"Kuba Mescidi","ru":"Мечеть Куба","en":"Quba Mosque","ar":"مسجد قباء"},{"az":"Əməvi məscidi","tr":"Emevi Camii","ru":"Мечеть Омейядов","en":"The Umayyad Mosque","ar":"المسجد الأموي"},{"az":"Məscidül-Həram","tr":"Mescid-i Haram","ru":"Аль-Масджид аль-Харам","en":"Al-Masjid al-Haram","ar":"المسجد الحرام"},{"az":"Məscidün-Nəbəvi","tr":"Mescid-i Nebevi","ru":"Мечеть Пророка","en":"The Prophet’s Mosque","ar":"المسجد النبوي"}],"correct":2,"explanation":{"az":"Bəqərə 2:144 Məscidül-Hərama yönəlməyi bildirir.","tr":"Bakara 2:144 Mescid-i Haram’a yönelmeyi bildirir.","ru":"Аль-Бакара 2:144 указывает на Аль-Масджид аль-Харам.","en":"Al-Baqarah 2:144 directs believers toward Al-Masjid al-Haram.","ar":"تأمر البقرة ٢:١٤٤ بالتوجه إلى المسجد الحرام."},"source_reference":"Quran 2:144","source_url":"https://quran.com/2/144","reviewed":true,"active":true,"topic":"prayer","tier":1,"concept_id":"prayer-01","option_ids":["prayer-01:0","prayer-01:1","prayer-01:2","prayer-01:3"],"correct_option_id":"prayer-01:2","review_status":"legacy-reviewed"}'::jsonb where id='prayer-01';
update shams_private.quiz_bank set payload='{"id":"prayer-02","category":"prayer","difficulty":1,"question":{"az":"Maidə surəsinin 6-cı ayəsində namazdan əvvəl hansı hazırlıq izah olunur?","tr":"Maide 5:6’da namazdan önce hangi hazırlık anlatılır?","ru":"Какая подготовка к молитве описана в Аль-Маида 5:6?","en":"What preparation for prayer is discussed in Al-Maidah 5:6?","ar":"ما الاستعداد للصلاة المذكور في المائدة ٥:٦؟"},"options":[{"az":"Həcc etmək","tr":"Hac yapmak","ru":"Паломничество","en":"Pilgrimage","ar":"الحج"},{"az":"Təmizlənmə və dəstəmaz","tr":"Temizlik ve abdest","ru":"Очищение и омовение","en":"Purification and ablution","ar":"الطهارة والوضوء"},{"az":"Qurban kəsmək","tr":"Kurban kesmek","ru":"Жертвоприношение","en":"Animal sacrifice","ar":"ذبح الأضحية"},{"az":"Sədəqə vermək","tr":"Sadaka vermek","ru":"Раздача милостыни","en":"Giving charity","ar":"الصدقة"}],"correct":1,"explanation":{"az":"Ayə namaza hazırlıqda təmizlənməni təsvir edir.","tr":"Ayet namaza hazırlıkta temizlenmeyi anlatır.","ru":"Аят описывает очищение перед молитвой.","en":"The verse describes purification before prayer.","ar":"تصف الآية الطهارة استعداداً للصلاة."},"source_reference":"Quran 5:6","source_url":"https://quran.com/5/6","reviewed":true,"active":true,"topic":"prayer","tier":1,"concept_id":"prayer-02","option_ids":["prayer-02:0","prayer-02:1","prayer-02:2","prayer-02:3"],"correct_option_id":"prayer-02:1","review_status":"legacy-reviewed"}'::jsonb where id='prayer-02';
update shams_private.quiz_bank set payload='{"id":"prayer-03","category":"prayer","difficulty":2,"question":{"az":"Cümə surəsinin 9-cu ayəsində namaza çağırış zamanı hansı işin dayandırılması buyurulur?","tr":"Cuma namazı çağrısında hangi işin bırakılması söylenir?","ru":"Какое занятие велено оставить при призыве к пятничной молитве?","en":"What activity should be left when the Friday prayer call is made?","ar":"أي عمل يُترك عند النداء لصلاة الجمعة؟"},"options":[{"az":"Alış-veriş","tr":"Alışveriş","ru":"Торговля","en":"Trade","ar":"البيع"},{"az":"Namaz","tr":"Namaz","ru":"Молитва","en":"Prayer","ar":"الصلاة"},{"az":"Allahı xatırlamaq","tr":"Allah’ı anmak","ru":"Поминание Аллаха","en":"Remembering Allah","ar":"ذكر الله"},{"az":"Dua","tr":"Dua","ru":"Дуа","en":"Supplication","ar":"الدعاء"}],"correct":0,"explanation":{"az":"Cümə 62:9 alış-verişi buraxıb zikrə yönəlməyi deyir.","tr":"Cuma 62:9 alışverişi bırakıp zikre yönelmeyi söyler.","ru":"Аль-Джумуа 62:9 велит оставить торговлю ради поминания.","en":"Al-Jumuah 62:9 says to leave trade for remembrance.","ar":"تأمر الجمعة ٦٢:٩ بترك البيع والسعي إلى الذكر."},"source_reference":"Quran 62:9","source_url":"https://quran.com/62/9","reviewed":true,"active":true,"topic":"prayer","tier":2,"concept_id":"prayer-03","option_ids":["prayer-03:0","prayer-03:1","prayer-03:2","prayer-03:3"],"correct_option_id":"prayer-03:0","review_status":"legacy-reviewed"}'::jsonb where id='prayer-03';
update shams_private.quiz_bank set payload='{"id":"prayer-04","category":"prayer","difficulty":1,"question":{"az":"Taha surəsinin 14-cü ayəsinə görə namazın məqsədlərindən biri nədir?","tr":"Taha 20:14’te namaz hangi amaçla ilişkilendirilir?","ru":"С какой целью связана молитва в Таха 20:14?","en":"What purpose is prayer linked to in Taha 20:14?","ar":"بأي غرض رُبطت الصلاة في طه ٢٠:١٤؟"},"options":[{"az":"Var-dövlət toplamaq","tr":"Servet biriktirmek","ru":"Накопление богатства","en":"Accumulating wealth","ar":"جمع المال"},{"az":"Şöhrət qazanmaq","tr":"Şöhret kazanmak","ru":"Поиск славы","en":"Seeking fame","ar":"طلب الشهرة"},{"az":"Rəqabət aparmaq","tr":"Rekabet etmek","ru":"Соперничество","en":"Competition","ar":"التنافس"},{"az":"Allahı xatırlamaq","tr":"Allah’ı anmak","ru":"Поминание Аллаха","en":"Remembering Allah","ar":"ذكر الله"}],"correct":3,"explanation":{"az":"Ayədə Allahı xatırlamaq üçün namaz qılmaq deyilir.","tr":"Ayette Allah’ı anmak için namaz kılmak söylenir.","ru":"Аят связывает молитву с поминанием Аллаха.","en":"The verse links establishing prayer to remembering Allah.","ar":"تربط الآية إقامة الصلاة بذكر الله."},"source_reference":"Quran 20:14","source_url":"https://quran.com/20/14","reviewed":true,"active":true,"topic":"prayer","tier":1,"concept_id":"prayer-04","option_ids":["prayer-04:0","prayer-04:1","prayer-04:2","prayer-04:3"],"correct_option_id":"prayer-04:3","review_status":"legacy-reviewed"}'::jsonb where id='prayer-04';
update shams_private.quiz_bank set payload='{"id":"prayer-05","category":"prayer","difficulty":2,"question":{"az":"Əraf surəsinin 31-ci ayəsində məscidə gedərkən nə ilə bağlı tövsiyə verilir?","tr":"Araf 7:31 ibadet yerinde hangi adabı öğretir?","ru":"Какой этикет места поклонения указан в Аль-Араф 7:31?","en":"What worship-place etiquette appears in Al-Araf 7:31?","ar":"ما أدب موضع العبادة في الأعراف ٧:٣١؟"},"options":[{"az":"İftar süfrəsi hazırlamaq","tr":"İftar hazırlamak","ru":"Готовить ифтар","en":"Preparing iftar","ar":"إعداد الإفطار"},{"az":"Ticarətə başlamaq","tr":"Ticarete başlamak","ru":"Начинать торговлю","en":"Starting trade","ar":"بدء التجارة"},{"az":"Münasib və səliqəli geyim","tr":"Uygun ve temiz kıyafet","ru":"Опрятная одежда","en":"Appropriate, tidy clothing","ar":"اللباس اللائق"},{"az":"Səfərə çıxmaq","tr":"Yolculuğa çıkmak","ru":"Отправиться в путь","en":"Setting out on a journey","ar":"السفر"}],"correct":2,"explanation":{"az":"Ayə ibadətdə uyğun geyimə diqqət çəkir.","tr":"Ayet ibadette uygun giyime dikkat çeker.","ru":"Аят обращает внимание на подобающую одежду.","en":"The verse draws attention to suitable dress for worship.","ar":"تلفت الآية إلى اللباس اللائق عند العبادة."},"source_reference":"Quran 7:31","source_url":"https://quran.com/7/31","reviewed":true,"active":true,"topic":"prayer","tier":2,"concept_id":"prayer-05","option_ids":["prayer-05:0","prayer-05:1","prayer-05:2","prayer-05:3"],"correct_option_id":"prayer-05:2","review_status":"legacy-reviewed"}'::jsonb where id='prayer-05';
update shams_private.quiz_bank set payload='{"id":"prayer-06","category":"prayer","difficulty":1,"question":{"az":"Bəqərə surəsinin 45-ci ayəsində namazla yanaşı nə ilə kömək istəmək tövsiyə olunur?","tr":"Kur’an’da namazla birlikte neyle yardım istenmesi söylenir?","ru":"Через что вместе с молитвой велено искать помощь?","en":"Alongside prayer, through what should help be sought?","ar":"بماذا يُستعان مع الصلاة؟"},"options":[{"az":"Qəzəb","tr":"Öfke","ru":"Гнев","en":"Anger","ar":"الغضب"},{"az":"Səbir","tr":"Sabır","ru":"Терпение","en":"Patience","ar":"الصبر"},{"az":"Təkəbbür","tr":"Kibir","ru":"Высокомерие","en":"Arrogance","ar":"الكبر"},{"az":"İsraf","tr":"İsraf","ru":"Расточительство","en":"Wastefulness","ar":"الإسراف"}],"correct":1,"explanation":{"az":"Bəqərə 2:45 səbir və namazla yardım istəməyi bildirir.","tr":"Bakara 2:45 sabır ve namazla yardım istemeyi bildirir.","ru":"Аль-Бакара 2:45 соединяет терпение и молитву.","en":"Al-Baqarah 2:45 joins patience and prayer in seeking help.","ar":"تجمع البقرة ٢:٤٥ بين الصبر والصلاة في الاستعانة."},"source_reference":"Quran 2:45","source_url":"https://quran.com/2/45","reviewed":true,"active":true,"topic":"prayer","tier":1,"concept_id":"prayer-06","option_ids":["prayer-06:0","prayer-06:1","prayer-06:2","prayer-06:3"],"correct_option_id":"prayer-06:1","review_status":"legacy-reviewed"}'::jsonb where id='prayer-06';
update shams_private.quiz_bank set payload='{"id":"prayer-07","category":"prayer","difficulty":2,"question":{"az":"Ənkəbut surəsinin 45-ci ayəsinə görə namaz insanı nədən çəkindirir?","tr":"Kur’an’a göre namaz insanı neden alıkoyar?","ru":"От чего, согласно Корану, удерживает молитва?","en":"According to the Quran, what should prayer deter?","ar":"عمّ تنهى الصلاة بحسب القرآن؟"},"options":[{"az":"Əxlaqsızlıq və pislik","tr":"Hayâsızlık ve kötülük","ru":"Мерзость и порицаемое","en":"Indecency and wrongdoing","ar":"الفحشاء والمنكر"},{"az":"Xeyirxahlıq","tr":"İyilik","ru":"Добродетель","en":"Kindness","ar":"الإحسان"},{"az":"Şükür","tr":"Şükür","ru":"Благодарность","en":"Gratitude","ar":"الشكر"},{"az":"Ədalət","tr":"Adalet","ru":"Справедливость","en":"Justice","ar":"العدل"}],"correct":0,"explanation":{"az":"Ənkəbut 29:45 namazın bu təsirini vurğulayır.","tr":"Ankebut 29:45 namazın bu etkisini vurgular.","ru":"Аль-Анкабут 29:45 подчёркивает это действие молитвы.","en":"Al-Ankabut 29:45 highlights this effect of prayer.","ar":"تؤكد العنكبوت ٢٩:٤٥ هذا الأثر للصلاة."},"source_reference":"Quran 29:45","source_url":"https://quran.com/29/45","reviewed":true,"active":true,"topic":"prayer","tier":2,"concept_id":"prayer-07","option_ids":["prayer-07:0","prayer-07:1","prayer-07:2","prayer-07:3"],"correct_option_id":"prayer-07:0","review_status":"legacy-reviewed"}'::jsonb where id='prayer-07';
update shams_private.quiz_bank set payload='{"id":"prayer-08","category":"prayer","difficulty":1,"question":{"az":"Bəqərə surəsinin 43-cü ayəsində namazla yanaşı hansı ibadət əmr edilir?","tr":"Bakara 2:43’te namazla birlikte hangi ibadet emredilir?","ru":"Какое поклонение вместе с молитвой велено в Аль-Бакара 2:43?","en":"Which act is commanded alongside prayer in Al-Baqarah 2:43?","ar":"ما العبادة المأمور بها مع الصلاة في البقرة ٢:٤٣؟"},"options":[{"az":"Həcc","tr":"Hac","ru":"Хадж","en":"Hajj","ar":"الحج"},{"az":"Etikaf","tr":"İtikâf","ru":"Итикаф","en":"Itikaf","ar":"الاعتكاف"},{"az":"Qurban","tr":"Kurban","ru":"Жертвоприношение","en":"Sacrifice","ar":"الأضحية"},{"az":"Zəkat","tr":"Zekât","ru":"Закят","en":"Zakat","ar":"الزكاة"}],"correct":3,"explanation":{"az":"Ayə namazı bərpa etməyi və zəkatı verməyi deyir.","tr":"Ayet namazı kılmayı ve zekâtı vermeyi söyler.","ru":"Аят велит совершать молитву и выплачивать закят.","en":"The verse commands prayer and giving zakat.","ar":"تأمر الآية بإقامة الصلاة وإيتاء الزكاة."},"source_reference":"Quran 2:43","source_url":"https://quran.com/2/43","reviewed":true,"active":true,"topic":"prayer","tier":1,"concept_id":"prayer-08","option_ids":["prayer-08:0","prayer-08:1","prayer-08:2","prayer-08:3"],"correct_option_id":"prayer-08:3","review_status":"legacy-reviewed"}'::jsonb where id='prayer-08';
update shams_private.quiz_bank set payload='{"id":"prayer-09","category":"prayer","difficulty":3,"question":{"az":"Nur surəsinin 58-ci ayəsində adı çəkilən səhər namazı hansıdır?","tr":"Nur 24:58’de adı geçen sabah namazı hangisidir?","ru":"Как называется рассветная молитва в Ан-Нур 24:58?","en":"What is the dawn prayer named in An-Nur 24:58?","ar":"ما اسم صلاة الصباح المذكورة في النور ٢٤:٥٨؟"},"options":[{"az":"Əsr","tr":"İkindi","ru":"Аср","en":"Asr","ar":"العصر"},{"az":"Məğrib","tr":"Akşam","ru":"Магриб","en":"Maghrib","ar":"المغرب"},{"az":"Fəcr (Sübh)","tr":"Fecr (Sabah)","ru":"Фаджр","en":"Fajr","ar":"الفجر"},{"az":"Zöhr","tr":"Öğle","ru":"Зухр","en":"Dhuhr","ar":"الظهر"}],"correct":2,"explanation":{"az":"Ayə fəcr namazından əvvəlki vaxtı qeyd edir.","tr":"Ayet fecr namazından önceki zamanı anar.","ru":"Аят упоминает время до молитвы Фаджр.","en":"The verse mentions the time before Fajr prayer.","ar":"تذكر الآية الوقت الذي قبل صلاة الفجر."},"source_reference":"Quran 24:58","source_url":"https://quran.com/24/58","reviewed":true,"active":true,"topic":"prayer","tier":3,"concept_id":"prayer-09","option_ids":["prayer-09:0","prayer-09:1","prayer-09:2","prayer-09:3"],"correct_option_id":"prayer-09:2","review_status":"legacy-reviewed"}'::jsonb where id='prayer-09';
update shams_private.quiz_bank set payload='{"id":"prayer-10","category":"prayer","difficulty":4,"question":{"az":"Nisa surəsinin 101-ci ayəsində namazı qısaltmaq hansı vəziyyətlə əlaqələndirilir?","tr":"Nisa 4:101’de namazın kısaltılması hangi durumda anılır?","ru":"При каком обстоятельстве в Ан-Ниса 4:101 упомянуто сокращение молитвы?","en":"In what context does An-Nisa 4:101 mention shortening prayer?","ar":"في أي سياق تذكر النساء ٤:١٠١ قصر الصلاة؟"},"options":[{"az":"Toy məclisi","tr":"Düğün","ru":"Свадьба","en":"A wedding","ar":"حفل زفاف"},{"az":"Səfər","tr":"Yolculuk","ru":"Путешествие","en":"Travel","ar":"السفر"},{"az":"Evdə rahatlıq","tr":"Evde rahatlık","ru":"Отдых дома","en":"Relaxing at home","ar":"الراحة في البيت"},{"az":"Ticarət gəliri","tr":"Ticaret kazancı","ru":"Торговая прибыль","en":"Business profit","ar":"الربح التجاري"}],"correct":1,"explanation":{"az":"Ayədə yola çıxmaq konteksti verilir; fiqhi təfərrüatlar ayrıca mövzudur.","tr":"Ayet yolculuk bağlamını verir; fıkhî ayrıntılar ayrı konudur.","ru":"Аят говорит о пути; подробности фикха рассматриваются отдельно.","en":"The verse gives a travel context; detailed legal conditions are a separate matter.","ar":"تذكر الآية سياق السفر، أما الشروط الفقهية التفصيلية فموضوع مستقل."},"source_reference":"Quran 4:101","source_url":"https://quran.com/4/101","reviewed":true,"active":true,"topic":"prayer","tier":3,"concept_id":"prayer-10","option_ids":["prayer-10:0","prayer-10:1","prayer-10:2","prayer-10:3"],"correct_option_id":"prayer-10:1","review_status":"legacy-reviewed"}'::jsonb where id='prayer-10';
update shams_private.quiz_bank set payload='{"id":"ramadan-01","category":"ramadan","difficulty":1,"question":{"az":"Bəqərə surəsinin 183-cü ayəsində orucun hansı məqsədi vurğulanır?","tr":"Kur’an’da orucun amaçlarından biri nasıl belirtilir?","ru":"Как в Коране выражена одна из целей поста?","en":"How does the Quran express one purpose of fasting?","ar":"كيف يعبّر القرآن عن إحدى غايات الصيام؟"},"options":[{"az":"Təqvaya yönəlmək","tr":"Takvaya yönelmek","ru":"Стремиться к богобоязненности","en":"Growing in mindfulness of Allah","ar":"تحقيق التقوى"},{"az":"Şöhrət qazanmaq","tr":"Şöhret kazanmak","ru":"Стать знаменитым","en":"Becoming famous","ar":"اكتساب الشهرة"},{"az":"Öyünmək","tr":"Övünmek","ru":"Хвастаться","en":"Boasting","ar":"التفاخر"},{"az":"Yalnız sərvət artırmaq","tr":"Yalnız servet artırmak","ru":"Лишь увеличить богатство","en":"Only increasing wealth","ar":"زيادة المال فقط"}],"correct":0,"explanation":{"az":"Bəqərə 2:183 orucu təqva ilə əlaqələndirir.","tr":"Bakara 2:183 orucu takvayla ilişkilendirir.","ru":"Аль-Бакара 2:183 связывает пост с богобоязненностью.","en":"Al-Baqarah 2:183 connects fasting with taqwa.","ar":"تربط البقرة ٢:١٨٣ الصيام بالتقوى."},"source_reference":"Quran 2:183","source_url":"https://quran.com/2/183","reviewed":true,"active":true,"topic":"ramadan","tier":1,"concept_id":"ramadan-01","option_ids":["ramadan-01:0","ramadan-01:1","ramadan-01:2","ramadan-01:3"],"correct_option_id":"ramadan-01:0","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-01';
update shams_private.quiz_bank set payload='{"id":"ramadan-02","category":"ramadan","difficulty":1,"question":{"az":"Bəqərə surəsinin 185-ci ayəsində Quranın nazil olduğu ay necə adlandırılır?","tr":"Kur’an’da Kur’an’ın indirildiği ay hangi adla anılır?","ru":"Какой месяц назван месяцем ниспослания Корана?","en":"Which month is named as the month of the Quran’s revelation?","ar":"أي شهر ذُكر أنه أُنزل فيه القرآن؟"},"options":[{"az":"Şəvval","tr":"Şevval","ru":"Шавваль","en":"Shawwal","ar":"شوال"},{"az":"Rəcəb","tr":"Recep","ru":"Раджаб","en":"Rajab","ar":"رجب"},{"az":"Məhərrəm","tr":"Muharrem","ru":"Мухаррам","en":"Muharram","ar":"محرم"},{"az":"Ramazan","tr":"Ramazan","ru":"Рамадан","en":"Ramadan","ar":"رمضان"}],"correct":3,"explanation":{"az":"Bəqərə 2:185 Ramazan ayının adını çəkir.","tr":"Bakara 2:185 Ramazan ayını adlandırır.","ru":"Аль-Бакара 2:185 прямо называет Рамадан.","en":"Al-Baqarah 2:185 explicitly names Ramadan.","ar":"تسمّي البقرة ٢:١٨٥ شهر رمضان."},"source_reference":"Quran 2:185","source_url":"https://quran.com/2/185","reviewed":true,"active":true,"topic":"ramadan","tier":1,"concept_id":"ramadan-02","option_ids":["ramadan-02:0","ramadan-02:1","ramadan-02:2","ramadan-02:3"],"correct_option_id":"ramadan-02:3","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-02';
update shams_private.quiz_bank set payload='{"id":"ramadan-03","category":"ramadan","difficulty":2,"question":{"az":"Bəqərə surəsinin 185-ci ayəsinə görə hansı hallarda buraxılan oruc başqa günlərdə tutulur?","tr":"Ramazan ayetinde hangi iki durum için başka günlerde tamamlama anılır?","ru":"Какие два обстоятельства названы для восполнения поста в другие дни?","en":"Which two circumstances are named for making up fasts on other days?","ar":"ما الحالتان المذكورتان لقضاء الصيام في أيام أخر؟"},"options":[{"az":"Sevinc və bayram","tr":"Sevinç ve bayram","ru":"Радость и праздник","en":"Joy and celebration","ar":"الفرح والاحتفال"},{"az":"Peşə və yaşadığı şəhər","tr":"Meslek ve yaşadığı şehir","ru":"Профессия и город","en":"Profession and city","ar":"المهنة والمدينة"},{"az":"Xəstəlik və səfər","tr":"Hastalık ve yolculuk","ru":"Болезнь и путешествие","en":"Illness and travel","ar":"المرض والسفر"},{"az":"Sərvət və şöhrət","tr":"Servet ve şöhret","ru":"Богатство и слава","en":"Wealth and fame","ar":"المال والشهرة"}],"correct":2,"explanation":{"az":"Bəqərə 2:185 xəstə və səfərdə olan şəxsi qeyd edir.","tr":"Bakara 2:185 hasta ve yolcu kişiyi anar.","ru":"Аль-Бакара 2:185 упоминает больного и путника.","en":"Al-Baqarah 2:185 mentions a person who is ill or travelling.","ar":"تذكر البقرة ٢:١٨٥ المريض والمسافر."},"source_reference":"Quran 2:185","source_url":"https://quran.com/2/185","reviewed":true,"active":true,"topic":"ramadan","tier":2,"concept_id":"ramadan-03","option_ids":["ramadan-03:0","ramadan-03:1","ramadan-03:2","ramadan-03:3"],"correct_option_id":"ramadan-03:2","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-03';
update shams_private.quiz_bank set payload='{"id":"ramadan-04","category":"ramadan","difficulty":1,"question":{"az":"Bəqərə surəsinin 185-ci ayəsində Allahın insanlar üçün nə istədiyi bildirilir?","tr":"Ramazan ayetinde Allah insanlar için ne istediğini bildirir?","ru":"Чего Аллах желает людям согласно аяту о Рамадане?","en":"What does Allah intend for people in the Ramadan verse?","ar":"ماذا يريد الله للناس في آية رمضان؟"},"options":[{"az":"İsraf","tr":"İsraf","ru":"Расточительство","en":"Waste","ar":"الإسراف"},{"az":"Asanlıq","tr":"Kolaylık","ru":"Облегчение","en":"Ease","ar":"اليسر"},{"az":"Çətinlik","tr":"Zorluk","ru":"Затруднение","en":"Hardship","ar":"العسر"},{"az":"Lovğalıq","tr":"Kibir","ru":"Высокомерие","en":"Arrogance","ar":"الكبر"}],"correct":1,"explanation":{"az":"Ayədə asanlıq istəndiyi, çətinlik istənmədiyi deyilir.","tr":"Ayette kolaylık istendiği, zorluk istenmediği söylenir.","ru":"Аят говорит о желании облегчения, а не затруднения.","en":"The verse states ease is intended, rather than hardship.","ar":"تقرر الآية إرادة اليسر لا العسر."},"source_reference":"Quran 2:185","source_url":"https://quran.com/2/185","reviewed":true,"active":true,"topic":"ramadan","tier":1,"concept_id":"ramadan-04","option_ids":["ramadan-04:0","ramadan-04:1","ramadan-04:2","ramadan-04:3"],"correct_option_id":"ramadan-04:1","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-04';
update shams_private.quiz_bank set payload='{"id":"ramadan-05","category":"ramadan","difficulty":2,"question":{"az":"Bəqərə surəsinin 187-ci ayəsinə görə orucluqda gecə yemək-içmək hansı vaxtadək davam edə bilər?","tr":"Oruç ayetinde yeme içme için hangi sınır belirtilir?","ru":"Какой рубеж для еды и питья указан в аяте о посте?","en":"What boundary for eating and drinking is described in the fasting verse?","ar":"ما الحد المذكور للأكل والشرب في آية الصيام؟"},"options":[{"az":"Fəcrin aydınlaşması","tr":"Fecrin belirmesi","ru":"Наступление рассвета","en":"The appearance of dawn","ar":"تبيّن الفجر"},{"az":"Günorta","tr":"Öğle","ru":"Полдень","en":"Noon","ar":"الظهر"},{"az":"Gecə yarısı","tr":"Gece yarısı","ru":"Полночь","en":"Midnight","ar":"منتصف الليل"},{"az":"İkindi","tr":"İkindi","ru":"Послеполуденное время","en":"Late afternoon","ar":"العصر"}],"correct":0,"explanation":{"az":"Bəqərə 2:187 fəcrin aydınlaşmasından danışır.","tr":"Bakara 2:187 fecrin belirmesinden söz eder.","ru":"Аль-Бакара 2:187 говорит о различении рассвета.","en":"Al-Baqarah 2:187 speaks of dawn becoming distinct.","ar":"تذكر البقرة ٢:١٨٧ تبيّن الفجر."},"source_reference":"Quran 2:187","source_url":"https://quran.com/2/187","reviewed":true,"active":true,"topic":"ramadan","tier":2,"concept_id":"ramadan-05","option_ids":["ramadan-05:0","ramadan-05:1","ramadan-05:2","ramadan-05:3"],"correct_option_id":"ramadan-05:0","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-05';
update shams_private.quiz_bank set payload='{"id":"ramadan-06","category":"ramadan","difficulty":2,"question":{"az":"Bəqərə surəsinin 187-ci ayəsində orucu nə vaxtadək tamamlamaq buyurulur?","tr":"Bakara 2:187’de orucun hangi vakte kadar tamamlanması söylenir?","ru":"До какого времени велено завершать пост в Аль-Бакара 2:187?","en":"Until what time is the fast to be completed in Al-Baqarah 2:187?","ar":"إلى أي وقت يُتم الصيام في البقرة ٢:١٨٧؟"},"options":[{"az":"Günortaya qədər","tr":"Öğleye kadar","ru":"До полудня","en":"Until noon","ar":"إلى الظهر"},{"az":"Növbəti həftəyə qədər","tr":"Gelecek haftaya kadar","ru":"До следующей недели","en":"Until next week","ar":"إلى الأسبوع التالي"},{"az":"İl sonuna qədər","tr":"Yıl sonuna kadar","ru":"До конца года","en":"Until year-end","ar":"إلى نهاية السنة"},{"az":"Gecəyə qədər","tr":"Geceye kadar","ru":"До ночи","en":"Until night","ar":"إلى الليل"}],"correct":3,"explanation":{"az":"Ayə orucun gecəyə qədər tamamlanmasını buyurur.","tr":"Ayet orucun geceye kadar tamamlanmasını buyurur.","ru":"Аят предписывает завершить пост до наступления ночи.","en":"The verse instructs completing the fast until night.","ar":"تأمر الآية بإتمام الصيام إلى الليل."},"source_reference":"Quran 2:187","source_url":"https://quran.com/2/187","reviewed":true,"active":true,"topic":"ramadan","tier":2,"concept_id":"ramadan-06","option_ids":["ramadan-06:0","ramadan-06:1","ramadan-06:2","ramadan-06:3"],"correct_option_id":"ramadan-06:3","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-06';
update shams_private.quiz_bank set payload='{"id":"ramadan-07","category":"ramadan","difficulty":3,"question":{"az":"Bəqərə surəsinin 187-ci ayəsində etikaf hansı məkanla əlaqələndirilir?","tr":"İtikâfla ilgili ayette hangi ibadet mekânı anılır?","ru":"Какое место поклонения названо в аяте об итикафе?","en":"Which worship place is mentioned in the verse about itikaf?","ar":"ما موضع العبادة المذكور في آية الاعتكاف؟"},"options":[{"az":"Saraylar","tr":"Saraylar","ru":"Дворцы","en":"Palaces","ar":"القصور"},{"az":"Limanlar","tr":"Limanlar","ru":"Порты","en":"Harbours","ar":"الموانئ"},{"az":"Məscidlər","tr":"Mescitler","ru":"Мечети","en":"Mosques","ar":"المساجد"},{"az":"Bazarlar","tr":"Pazarlar","ru":"Рынки","en":"Markets","ar":"الأسواق"}],"correct":2,"explanation":{"az":"Bəqərə 2:187 məscidlərdə etikafdan bəhs edir.","tr":"Bakara 2:187 mescitlerde itikâftan söz eder.","ru":"Аль-Бакара 2:187 упоминает итикаф в мечетях.","en":"Al-Baqarah 2:187 mentions itikaf in mosques.","ar":"تذكر البقرة ٢:١٨٧ الاعتكاف في المساجد."},"source_reference":"Quran 2:187","source_url":"https://quran.com/2/187","reviewed":true,"active":true,"topic":"ramadan","tier":3,"concept_id":"ramadan-07","option_ids":["ramadan-07:0","ramadan-07:1","ramadan-07:2","ramadan-07:3"],"correct_option_id":"ramadan-07:2","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-07';
update shams_private.quiz_bank set payload='{"id":"ramadan-08","category":"ramadan","difficulty":1,"question":{"az":"Bəqərə surəsinin 183-cü ayəsinə görə əvvəlki ümmətlərə də oruc vacib edilmişdimi?","tr":"Kur’an’a göre oruç önceki topluluklara da farz kılınmış mıydı?","ru":"Был ли, согласно Корану, пост предписан прежним общинам?","en":"According to the Quran, was fasting prescribed to earlier communities too?","ar":"هل كُتب الصيام على أمم سابقة بحسب القرآن؟"},"options":[{"az":"Heç kimə yazılmayıb","tr":"Hiç kimseye farz değildi","ru":"Не был предписан никому","en":"It was prescribed to nobody","ar":"لم يُكتب على أحد"},{"az":"Bəli, əvvəlkilərə də","tr":"Evet, öncekilere de","ru":"Да, прежним общинам тоже","en":"Yes, to earlier communities too","ar":"نعم، كُتب على السابقين أيضاً"},{"az":"Yalnız bir ailəyə","tr":"Yalnız bir aileye","ru":"Только одной семье","en":"Only to one family","ar":"لأسرة واحدة فقط"},{"az":"Yalnız hökmdarlara","tr":"Yalnız hükümdarlara","ru":"Только правителям","en":"Only to rulers","ar":"للحكام فقط"}],"correct":1,"explanation":{"az":"Bəqərə 2:183 əvvəlki ümmətləri açıq xatırladır.","tr":"Bakara 2:183 önceki toplulukları açıkça anar.","ru":"Аль-Бакара 2:183 прямо упоминает прежние общины.","en":"Al-Baqarah 2:183 explicitly mentions earlier communities.","ar":"تذكر البقرة ٢:١٨٣ الذين من قبلنا."},"source_reference":"Quran 2:183","source_url":"https://quran.com/2/183","reviewed":true,"active":true,"topic":"ramadan","tier":1,"concept_id":"ramadan-08","option_ids":["ramadan-08:0","ramadan-08:1","ramadan-08:2","ramadan-08:3"],"correct_option_id":"ramadan-08:1","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-08';
update shams_private.quiz_bank set payload='{"id":"ramadan-09","category":"ramadan","difficulty":3,"question":{"az":"Qədr surəsinə görə Qədr gecəsi neçə aydan xeyirlidir?","tr":"Kadir gecesi Kur’an’da ne kadar süreden hayırlı sayılır?","ru":"Лучше какого срока названа Ночь предопределения?","en":"The Night of Decree is better than what length of time?","ar":"ليلة القدر خير من أي مدة؟"},"options":[{"az":"Min ay","tr":"Bin ay","ru":"Тысяча месяцев","en":"A thousand months","ar":"ألف شهر"},{"az":"On gün","tr":"On gün","ru":"Десять дней","en":"Ten days","ar":"عشرة أيام"},{"az":"Yeddi həftə","tr":"Yedi hafta","ru":"Семь недель","en":"Seven weeks","ar":"سبعة أسابيع"},{"az":"Bir mövsüm","tr":"Bir mevsim","ru":"Один сезон","en":"One season","ar":"فصل واحد"}],"correct":0,"explanation":{"az":"Qədr 97:3-də min ay müqayisəsi verilir.","tr":"Kadir 97:3’te bin ay karşılaştırması verilir.","ru":"Аль-Кадр 97:3 указывает тысячу месяцев.","en":"Al-Qadr 97:3 gives the comparison of a thousand months.","ar":"تذكر القدر ٩٧:٣ المقارنة بألف شهر."},"source_reference":"Quran 97:3","source_url":"https://quran.com/97/3","reviewed":true,"active":true,"topic":"ramadan","tier":3,"concept_id":"ramadan-09","option_ids":["ramadan-09:0","ramadan-09:1","ramadan-09:2","ramadan-09:3"],"correct_option_id":"ramadan-09:0","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-09';
update shams_private.quiz_bank set payload='{"id":"ramadan-10","category":"ramadan","difficulty":4,"question":{"az":"Bəqərə surəsinin 184-cü ayəsində fidyə hansı yardımla izah edilir?","tr":"Bakara 2:184’te fidye hangi yardımla ilişkilendirilir?","ru":"С какой помощью связана фидья в Аль-Бакара 2:184?","en":"What kind of aid is fidyah linked to in Al-Baqarah 2:184?","ar":"بأي مساعدة رُبطت الفدية في البقرة ٢:١٨٤؟"},"options":[{"az":"Saray tikmək","tr":"Saray yapmak","ru":"Построить дворец","en":"Building a palace","ar":"بناء قصر"},{"az":"Zinət almaq","tr":"Takı almak","ru":"Купить украшения","en":"Buying jewellery","ar":"شراء الحلي"},{"az":"Şöhrət qazanmaq","tr":"Şöhret kazanmak","ru":"Добиться славы","en":"Gaining fame","ar":"اكتساب الشهرة"},{"az":"Ehtiyacı olanı yedirtmək","tr":"Yoksulu doyurmak","ru":"Накормить нуждающегося","en":"Feeding a person in need","ar":"إطعام مسكين"}],"correct":3,"explanation":{"az":"Ayədə fidyə ilə miskini yedirtmək arasında əlaqə qurulur; şəxsi hökm ayrıca soruşulmalıdır.","tr":"Ayette fidye yoksulu doyurmakla ilişkilidir; kişisel hüküm ayrıca sorulmalıdır.","ru":"Аят связывает фидью с кормлением нуждающегося; личные условия требуют отдельного разъяснения.","en":"The verse links fidyah to feeding a needy person; individual rulings require separate guidance.","ar":"تربط الآية الفدية بإطعام مسكين، وأحكام الحالات الفردية تُسأل على حدة."},"source_reference":"Quran 2:184","source_url":"https://quran.com/2/184","reviewed":true,"active":true,"topic":"ramadan","tier":3,"concept_id":"ramadan-10","option_ids":["ramadan-10:0","ramadan-10:1","ramadan-10:2","ramadan-10:3"],"correct_option_id":"ramadan-10:3","review_status":"legacy-reviewed"}'::jsonb where id='ramadan-10';
update shams_private.quiz_bank set payload='{"id":"culture-01","category":"culture","difficulty":1,"question":{"az":"Nisa surəsinin 86-cı ayəsinə görə verilən salama necə cavab verilməlidir?","tr":"Selam verildiğinde Kur’an nasıl karşılık vermeyi öğretir?","ru":"Как Коран учит отвечать на приветствие?","en":"How does the Quran teach us to answer a greeting?","ar":"كيف يعلّم القرآن رد التحية؟"},"options":[{"az":"Təhqirlə","tr":"Hakaretle","ru":"Оскорблением","en":"With an insult","ar":"بالإهانة"},{"az":"Yalnız pul verməklə","tr":"Yalnız para vererek","ru":"Только деньгами","en":"Only by giving money","ar":"بالمال فقط"},{"az":"Daha gözəli və ya eynisi ilə","tr":"Daha güzeli veya aynısıyla","ru":"Лучше или так же","en":"With a better or equal greeting","ar":"بأحسن منها أو مثلها"},{"az":"Həmişə susmaqla","tr":"Her zaman susarak","ru":"Всегда молчанием","en":"Always with silence","ar":"بالصمت دائماً"}],"correct":2,"explanation":{"az":"Nisa 4:86 salamı daha gözəli və ya bənzəri ilə qaytarmağı deyir.","tr":"Nisa 4:86 selamı daha güzeli veya benzeriyle karşılamayı söyler.","ru":"Ан-Ниса 4:86 предписывает ответить лучше или подобным образом.","en":"An-Nisa 4:86 teaches responding better or similarly.","ar":"تعلّم النساء ٤:٨٦ الرد بأحسن من التحية أو بمثلها."},"source_reference":"Quran 4:86","source_url":"https://quran.com/4/86","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"culture-01","option_ids":["culture-01:0","culture-01:1","culture-01:2","culture-01:3"],"correct_option_id":"culture-01:2","review_status":"legacy-reviewed"}'::jsonb where id='culture-01';
update shams_private.quiz_bank set payload='{"id":"culture-02","category":"culture","difficulty":1,"question":{"az":"Nisa surəsinin 58-ci ayəsinə görə əmanətlər kimə qaytarılmalıdır?","tr":"Kur’an emanetleri kime vermeyi emreder?","ru":"Кому Коран велит возвращать доверенное?","en":"To whom does the Quran command trusts to be returned?","ar":"إلى من يأمر القرآن بأداء الأمانات؟"},"options":[{"az":"Ən güclü şəxsə","tr":"En güçlü kişiye","ru":"Самому сильному","en":"The strongest person","ar":"الأقوى"},{"az":"Haqq sahiblərinə","tr":"Hak sahiplerine","ru":"Законным владельцам","en":"Their rightful owners","ar":"أهلها"},{"az":"Yalnız varlılara","tr":"Yalnız zenginlere","ru":"Только богатым","en":"Only the rich","ar":"الأغنياء فقط"},{"az":"Heç kimə","tr":"Hiç kimseye","ru":"Никому","en":"Nobody","ar":"لا أحد"}],"correct":1,"explanation":{"az":"Nisa 4:58 əmanətləri sahiblərinə qaytarmağı buyurur.","tr":"Nisa 4:58 emanetleri ehline vermeyi buyurur.","ru":"Ан-Ниса 4:58 повелевает вернуть доверенное владельцам.","en":"An-Nisa 4:58 commands returning trusts to their owners.","ar":"تأمر النساء ٤:٥٨ بأداء الأمانات إلى أهلها."},"source_reference":"Quran 4:58","source_url":"https://quran.com/4/58","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"culture-02","option_ids":["culture-02:0","culture-02:1","culture-02:2","culture-02:3"],"correct_option_id":"culture-02:1","review_status":"legacy-reviewed"}'::jsonb where id='culture-02';
update shams_private.quiz_bank set payload='{"id":"culture-03","category":"culture","difficulty":2,"question":{"az":"Maidə surəsinin 1-ci ayəsində müqavilələrlə bağlı nə buyurulur?","tr":"Maide 5:1’de hangi davranış emredilir?","ru":"Какое поведение предписано в Аль-Маида 5:1?","en":"What conduct is commanded in Al-Maidah 5:1?","ar":"ما السلوك المأمور به في المائدة ٥:١؟"},"options":[{"az":"Əhd və müqavilələrə riayət","tr":"Akitlere bağlılık","ru":"Соблюдение обязательств","en":"Honouring agreements","ar":"الوفاء بالعقود"},{"az":"Həmişə sözü pozmaq","tr":"Daima söz bozmak","ru":"Всегда нарушать слово","en":"Always breaking promises","ar":"نقض العهود دائماً"},{"az":"Aldatmaq","tr":"Aldatmak","ru":"Обман","en":"Deception","ar":"الخداع"},{"az":"Əmanəti gizlətmək","tr":"Emaneti gizlemek","ru":"Присвоение доверенного","en":"Concealing trusts","ar":"كتمان الأمانات"}],"correct":0,"explanation":{"az":"Ayənin əvvəlində müqavilələrə sadiqlik vurğulanır.","tr":"Ayetin başında akitlere bağlılık vurgulanır.","ru":"Начало аята подчёркивает исполнение обязательств.","en":"The opening of the verse stresses fulfilling agreements.","ar":"تؤكد بداية الآية الوفاء بالعقود."},"source_reference":"Quran 5:1","source_url":"https://quran.com/5/1","reviewed":true,"active":true,"topic":"general","tier":2,"concept_id":"culture-03","option_ids":["culture-03:0","culture-03:1","culture-03:2","culture-03:3"],"correct_option_id":"culture-03:0","review_status":"legacy-reviewed"}'::jsonb where id='culture-03';
update shams_private.quiz_bank set payload='{"id":"culture-04","category":"culture","difficulty":1,"question":{"az":"İsra surəsinin 35-ci ayəsinə görə ticarətdə ölçü və çəki necə olmalıdır?","tr":"Kur’an ticarette ölçü ve tartı hakkında ne söyler?","ru":"Что Коран говорит о мере и весе в торговле?","en":"What does the Quran teach about measures and weights in trade?","ar":"ماذا يعلّم القرآن عن الكيل والميزان؟"},"options":[{"az":"Müştəriyə görə dəyişsin","tr":"Müşteriye göre değişsin","ru":"Менять по покупателю","en":"Change them by customer","ar":"تغييرها بحسب المشتري"},{"az":"Gizli azaldılsın","tr":"Gizlice azaltılsın","ru":"Тайно уменьшать","en":"Reduce them secretly","ar":"إنقاصها سراً"},{"az":"Çəkiyə ehtiyac yoxdur","tr":"Tartıya gerek yok","ru":"Вес не нужен","en":"No weighing is needed","ar":"لا حاجة للوزن"},{"az":"Tam və ədalətli olsun","tr":"Tam ve adil olsun","ru":"Полная и справедливая мера","en":"Use full and fair measures","ar":"إيفاء الكيل والوزن بالعدل"}],"correct":3,"explanation":{"az":"İsra 17:35 tam ölçü və düzgün tərəzi öyrədir.","tr":"İsra 17:35 tam ölçü ve doğru tartıyı öğretir.","ru":"Аль-Исра 17:35 учит полной мере и верным весам.","en":"Al-Isra 17:35 teaches full measure and accurate balance.","ar":"تعلّم الإسراء ١٧:٣٥ إيفاء الكيل والميزان المستقيم."},"source_reference":"Quran 17:35","source_url":"https://quran.com/17/35","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"culture-04","option_ids":["culture-04:0","culture-04:1","culture-04:2","culture-04:3"],"correct_option_id":"culture-04:3","review_status":"legacy-reviewed"}'::jsonb where id='culture-04';
update shams_private.quiz_bank set payload='{"id":"culture-05","category":"culture","difficulty":1,"question":{"az":"İsra surəsinin 23-cü ayəsinə görə valideynlərlə necə danışmaq lazımdır?","tr":"Anne babayla konuşurken Kur’an neyi öğretir?","ru":"Как Коран учит разговаривать с родителями?","en":"What speech does the Quran teach towards parents?","ar":"ما أدب الكلام مع الوالدين في القرآن؟"},"options":[{"az":"Səbəbsiz qışqırıq","tr":"Sebepsiz bağırmak","ru":"Беспричинный крик","en":"Unprovoked shouting","ar":"الصراخ بلا سبب"},{"az":"İstehza","tr":"Alay","ru":"Насмешка","en":"Mockery","ar":"السخرية"},{"az":"Hörmətli və gözəl söz","tr":"Saygılı ve güzel söz","ru":"Уважительные слова","en":"Respectful and noble speech","ar":"قول كريم"},{"az":"Təhqir","tr":"Hakaret","ru":"Оскорбление","en":"Insults","ar":"الإهانة"}],"correct":2,"explanation":{"az":"İsra 17:23 valideynlərə xoş söz deməyi bildirir.","tr":"İsra 17:23 anne babaya güzel söz söylemeyi bildirir.","ru":"Аль-Исра 17:23 велит говорить с родителями достойно.","en":"Al-Isra 17:23 instructs noble speech to parents.","ar":"تأمر الإسراء ١٧:٢٣ بالقول الكريم للوالدين."},"source_reference":"Quran 17:23","source_url":"https://quran.com/17/23","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"culture-05","option_ids":["culture-05:0","culture-05:1","culture-05:2","culture-05:3"],"correct_option_id":"culture-05:2","review_status":"legacy-reviewed"}'::jsonb where id='culture-05';
update shams_private.quiz_bank set payload='{"id":"culture-06","category":"culture","difficulty":2,"question":{"az":"Hucurat surəsinin 11-ci ayəsində hansı davranışdan çəkinmək buyurulur?","tr":"Hucurat 49:11 hangi davranıştan sakındırır?","ru":"От какого поведения предостерегает Аль-Худжурат 49:11?","en":"Which conduct does Al-Hujurat 49:11 warn against?","ar":"عن أي سلوك تنهى الحجرات ٤٩:١١؟"},"options":[{"az":"Elm öyrənmək","tr":"İlim öğrenmek","ru":"Учёба","en":"Learning","ar":"التعلم"},{"az":"Başqalarını ələ salmaq","tr":"Başkalarıyla alay etmek","ru":"Высмеивание других","en":"Mocking others","ar":"السخرية بالآخرين"},{"az":"Ədalət","tr":"Adalet","ru":"Справедливость","en":"Justice","ar":"العدل"},{"az":"Hədiyyə vermək","tr":"Hediye vermek","ru":"Дарение подарков","en":"Giving gifts","ar":"إهداء الهدايا"}],"correct":1,"explanation":{"az":"Ayədə bir topluluğun digərini ələ salmaması deyilir.","tr":"Ayette bir topluluğun diğerini küçümsememesi söylenir.","ru":"Аят запрещает одной группе насмехаться над другой.","en":"The verse warns one group not to ridicule another.","ar":"تنهى الآية عن سخرية قوم من قوم."},"source_reference":"Quran 49:11","source_url":"https://quran.com/49/11","reviewed":true,"active":true,"topic":"general","tier":2,"concept_id":"culture-06","option_ids":["culture-06:0","culture-06:1","culture-06:2","culture-06:3"],"correct_option_id":"culture-06:1","review_status":"legacy-reviewed"}'::jsonb where id='culture-06';
update shams_private.quiz_bank set payload='{"id":"culture-07","category":"culture","difficulty":2,"question":{"az":"Hucurat surəsinin 12-ci ayəsində hansı mənfi davranış qadağan edilir?","tr":"Hucurat 49:12’de hangi olumsuz davranış yasaklanır?","ru":"Какое отрицательное поведение запрещено в Аль-Худжурат 49:12?","en":"Which negative conduct is prohibited in Al-Hujurat 49:12?","ar":"ما السلوك السلبي المنهي عنه في الحجرات ٤٩:١٢؟"},"options":[{"az":"Qeybət","tr":"Gıybet","ru":"Злословие","en":"Backbiting","ar":"الغيبة"},{"az":"Şükür","tr":"Şükür","ru":"Благодарность","en":"Gratitude","ar":"الشكر"},{"az":"Qonaqpərvərlik","tr":"Misafirperverlik","ru":"Гостеприимство","en":"Hospitality","ar":"الضيافة"},{"az":"Xeyriyyə","tr":"Hayır","ru":"Благотворительность","en":"Charity","ar":"الصدقة"}],"correct":0,"explanation":{"az":"Ayə qeybətdən və gizli araşdırmadan çəkindirir.","tr":"Ayet gıybetten ve gizlice araştırmaktan sakındırır.","ru":"Аят предостерегает от злословия и слежки.","en":"The verse warns against backbiting and spying.","ar":"تنهى الآية عن الغيبة والتجسس."},"source_reference":"Quran 49:12","source_url":"https://quran.com/49/12","reviewed":true,"active":true,"topic":"general","tier":2,"concept_id":"culture-07","option_ids":["culture-07:0","culture-07:1","culture-07:2","culture-07:3"],"correct_option_id":"culture-07:0","review_status":"legacy-reviewed"}'::jsonb where id='culture-07';
update shams_private.quiz_bank set payload='{"id":"culture-08","category":"culture","difficulty":1,"question":{"az":"Nur surəsinin 27-ci ayəsinə görə başqasının evinə girməzdən əvvəl nə etmək lazımdır?","tr":"Başkasının evine girmeden önce Kur’an neyi öğretir?","ru":"Что Коран предписывает перед входом в чужой дом?","en":"What does the Quran teach before entering another person’s home?","ar":"ماذا يعلّم القرآن قبل دخول بيت غير بيتك؟"},"options":[{"az":"İcazəsiz daxil olmaq","tr":"İzinsiz girmek","ru":"Входить без разрешения","en":"Enter without permission","ar":"الدخول بلا إذن"},{"az":"Əşyaları araşdırmaq","tr":"Eşyaları araştırmak","ru":"Обыскивать вещи","en":"Search possessions","ar":"تفتيش المتاع"},{"az":"Qapını sındırmaq","tr":"Kapıyı kırmak","ru":"Ломать дверь","en":"Break the door","ar":"كسر الباب"},{"az":"İcazə istəmək və salam vermək","tr":"İzin istemek ve selam vermek","ru":"Просить разрешения и приветствовать","en":"Ask permission and greet","ar":"الاستئذان والسلام"}],"correct":3,"explanation":{"az":"Nur 24:27 icazə və salam ədəbini bildirir.","tr":"Nur 24:27 izin ve selam adabını bildirir.","ru":"Ан-Нур 24:27 учит разрешению и приветствию.","en":"An-Nur 24:27 teaches permission and greeting.","ar":"تعلّم النور ٢٤:٢٧ أدب الاستئذان والسلام."},"source_reference":"Quran 24:27","source_url":"https://quran.com/24/27","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"culture-08","option_ids":["culture-08:0","culture-08:1","culture-08:2","culture-08:3"],"correct_option_id":"culture-08:3","review_status":"legacy-reviewed"}'::jsonb where id='culture-08';
update shams_private.quiz_bank set payload='{"id":"culture-09","category":"culture","difficulty":3,"question":{"az":"Bəqərə surəsinin 168-ci ayəsinə görə yerdəki ruzidən necə yemək lazımdır?","tr":"Kur’an yeryüzündeki rızıktan nasıl yemeyi buyurur?","ru":"Какую пищу Коран велит употреблять из земного удела?","en":"What kind of earthly provision does the Quran say to eat?","ar":"أي طعام من رزق الأرض يأمر القرآن بأكله؟"},"options":[{"az":"Yalnız nadir","tr":"Yalnız nadir","ru":"Только редкое","en":"Only rare food","ar":"النادر فقط"},{"az":"İstənilən oğurluq mal","tr":"Her çalıntı mal","ru":"Всё украденное","en":"Any stolen goods","ar":"كل مسروق"},{"az":"Halal və pak","tr":"Helal ve temiz","ru":"Дозволенное и благое","en":"Lawful and good","ar":"الحلال الطيب"},{"az":"Yalnız bahalı","tr":"Yalnız pahalı","ru":"Только дорогое","en":"Only expensive food","ar":"الغالي فقط"}],"correct":2,"explanation":{"az":"Bəqərə 2:168 halal və təmiz ruzidən danışır.","tr":"Bakara 2:168 helal ve temiz rızkı anlatır.","ru":"Аль-Бакара 2:168 говорит о дозволенном и благом.","en":"Al-Baqarah 2:168 speaks of lawful, good provision.","ar":"تذكر البقرة ٢:١٦٨ الحلال الطيب."},"source_reference":"Quran 2:168","source_url":"https://quran.com/2/168","reviewed":true,"active":true,"topic":"general","tier":3,"concept_id":"culture-09","option_ids":["culture-09:0","culture-09:1","culture-09:2","culture-09:3"],"correct_option_id":"culture-09:2","review_status":"legacy-reviewed"}'::jsonb where id='culture-09';
update shams_private.quiz_bank set payload='{"id":"culture-10","category":"culture","difficulty":4,"question":{"az":"Əraf surəsinin 31-ci ayəsində yeyib-içərkən nədən çəkinmək buyurulur?","tr":"Yeme içmeyle ilgili ayet hangi alışkanlıktan sakındırır?","ru":"От какой привычки предостерегает аят о еде и питье?","en":"What habit does the verse about eating and drinking warn against?","ar":"عن أي عادة تنهى آية الأكل والشرب؟"},"options":[{"az":"Halal ruzi","tr":"Helal rızık","ru":"Дозволенный удел","en":"Lawful provision","ar":"الرزق الحلال"},{"az":"İsraf","tr":"İsraf","ru":"Расточительство","en":"Wastefulness","ar":"الإسراف"},{"az":"Şükür","tr":"Şükür","ru":"Благодарность","en":"Gratitude","ar":"الشكر"},{"az":"Paylaşmaq","tr":"Paylaşmak","ru":"Делиться","en":"Sharing","ar":"المشاركة"}],"correct":1,"explanation":{"az":"Əraf 7:31 yemək və içməkdə israfı rədd edir.","tr":"Araf 7:31 yeme içmede israfı reddeder.","ru":"Аль-Араф 7:31 отвергает расточительство в еде и питье.","en":"Al-Araf 7:31 rejects waste in eating and drinking.","ar":"تنهى الأعراف ٧:٣١ عن الإسراف في الأكل والشرب."},"source_reference":"Quran 7:31","source_url":"https://quran.com/7/31","reviewed":true,"active":true,"topic":"general","tier":3,"concept_id":"culture-10","option_ids":["culture-10:0","culture-10:1","culture-10:2","culture-10:3"],"correct_option_id":"culture-10:1","review_status":"legacy-reviewed"}'::jsonb where id='culture-10';
