update shams_private.quiz_bank set payload='{"id":"names-10","category":"names","difficulty":4,"question":{"az":"“Əs-Səmi” (السَّمِيع) adının mənası nədir?","tr":"“السَّمِيع” isminin anlamı hangisidir?","ru":"Что означает имя «السَّمِيع»?","en":"What does the name “السَّمِيع” mean?","ar":"ما معنى اسم «السَّمِيع»؟"},"options":[{"az":"Surət və forma verən","tr":"Şekil ve suret veren","ru":"Придающий облик","en":"The Fashioner","ar":"المعطي الصور"},{"az":"Mütləq hökmran","tr":"Mutlak hükümdar","ru":"Владыка","en":"The Sovereign","ar":"الملك ذو السلطان"},{"az":"Müqəddəs, nöqsanlardan uzaq","tr":"Kutsal, eksiklikten uzak","ru":"Пресвятой","en":"The Most Holy","ar":"المنزّه عن النقائص"},{"az":"Hər şeyi eşidən","tr":"Her şeyi işiten","ru":"Всеслышащий","en":"The All-Hearing","ar":"السميع لكل شيء"}],"correct":3,"explanation":{"az":"السَّمِيع adı 2:127 ayəsində işlənir; mənası: Hər şeyi eşidən.","tr":"السَّمِيع ismi 2:127 ayetinde geçer; anlamı: Her şeyi işiten.","ru":"Имя السَّمِيع встречается в 2:127; значение: Всеслышащий.","en":"السَّمِيع occurs in 2:127; its meaning is The All-Hearing.","ar":"يرد اسم السَّمِيع في 2:127؛ ومعناه: السميع لكل شيء."},"source_reference":"Quran 2:127","source_url":"https://quran.com/2/127","reviewed":true,"active":true,"topic":"basics","tier":3,"concept_id":"names-10","option_ids":["names-10:0","names-10:1","names-10:2","names-10:3"],"correct_option_id":"names-10:3","review_status":"legacy-reviewed"}'::jsonb where id='names-10';
update shams_private.quiz_bank set payload='{"id":"general-01","category":"general","difficulty":1,"question":{"az":"Bəqərə surəsinin 271-ci ayəsində ehtiyacı olana gizli sədəqə vermək necə qiymətləndirilir?","tr":"Kur’an yoksullara gizlice sadaka vermeyi nasıl değerlendirir?","ru":"Как Коран оценивает тайную милостыню бедным?","en":"How does the Quran regard private charity to the poor?","ar":"كيف يصف القرآن إخفاء الصدقة للفقراء؟"},"options":[{"az":"Mənasız","tr":"Anlamsız","ru":"Бессмысленно","en":"Meaningless","ar":"بلا معنى"},{"az":"Yalnız varlılar üçündür","tr":"Yalnız zenginler içindir","ru":"Только для богатых","en":"Only for the rich","ar":"للأغنياء فقط"},{"az":"Daha xeyirli","tr":"Daha hayırlı","ru":"Лучше","en":"Better","ar":"خير"},{"az":"Həmişə qadağan","tr":"Her zaman yasak","ru":"Всегда запрещено","en":"Always forbidden","ar":"ممنوع دائماً"}],"correct":2,"explanation":{"az":"Bəqərə 2:271 gizli verməyi daha xeyirli adlandırır.","tr":"Bakara 2:271 gizli vermeyi daha hayırlı olarak niteler.","ru":"Аль-Бакара 2:271 называет тайную помощь более благой.","en":"Al-Baqarah 2:271 calls private giving better.","ar":"تصف البقرة ٢:٢٧١ إخفاء الصدقة بأنه خير."},"source_reference":"Quran 2:271","source_url":"https://quran.com/2/271","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"general-01","option_ids":["general-01:0","general-01:1","general-01:2","general-01:3"],"correct_option_id":"general-01:2","review_status":"legacy-reviewed"}'::jsonb where id='general-01';
update shams_private.quiz_bank set payload='{"id":"general-02","category":"general","difficulty":2,"question":{"az":"Ali-İmran surəsinin 92-ci ayəsinə görə yaxşılığa çatmaq üçün nədən xərcləmək lazımdır?","tr":"Âl-i İmran 3:92 iyiliğe ulaşmak için neden vermeyi hatırlatır?","ru":"Из чего Аль-Имран 3:92 призывает жертвовать ради благочестия?","en":"What does Ali Imran 3:92 mention giving from to attain righteousness?","ar":"ممّ تدعو آل عمران ٣:٩٢ إلى الإنفاق لنيل البر؟"},"options":[{"az":"Yalnız şöhrət üçün","tr":"Yalnız şöhret için","ru":"Только ради славы","en":"Only for fame","ar":"للشهرة فقط"},{"az":"Sevdiklərindən","tr":"Sevdiklerinden","ru":"Из любимого","en":"What one cherishes","ar":"مما تحبون"},{"az":"Yalnız yararsız əşyalardan","tr":"Yalnız işe yaramaz eşyalardan","ru":"Только из ненужного","en":"Only useless things","ar":"الأشياء التالفة فقط"},{"az":"Başqasının malından","tr":"Başkasının malından","ru":"Из чужого имущества","en":"Another person’s property","ar":"مال الآخرين"}],"correct":1,"explanation":{"az":"Ayədə sevilən şeylərdən sərf etmək vurğulanır.","tr":"Ayette sevilen şeylerden harcamak vurgulanır.","ru":"Аят подчёркивает жертвование из дорогого человеку.","en":"The verse emphasizes giving from what one values.","ar":"تؤكد الآية الإنفاق مما يحب الإنسان."},"source_reference":"Quran 3:92","source_url":"https://quran.com/3/92","reviewed":true,"active":true,"topic":"general","tier":2,"concept_id":"general-02","option_ids":["general-02:0","general-02:1","general-02:2","general-02:3"],"correct_option_id":"general-02:1","review_status":"legacy-reviewed"}'::jsonb where id='general-02';
update shams_private.quiz_bank set payload='{"id":"general-03","category":"general","difficulty":1,"question":{"az":"Bəqərə surəsinin 256-cı ayəsində dinlə bağlı hansı prinsip bildirilir?","tr":"Bakara 2:256 din konusunda hangi ilkeden söz eder?","ru":"О каком принципе в религии говорит Аль-Бакара 2:256?","en":"Which principle about religion is stated in Al-Baqarah 2:256?","ar":"ما المبدأ المتعلق بالدين في البقرة ٢:٢٥٦؟"},"options":[{"az":"Dində məcburiyyət yoxdur","tr":"Dinde zorlama yoktur","ru":"Нет принуждения в религии","en":"No compulsion in religion","ar":"لا إكراه في الدين"},{"az":"İsraf məcburidir","tr":"İsraf zorunludur","ru":"Расточительство обязательно","en":"Waste is compulsory","ar":"الإسراف واجب"},{"az":"Əmanət qaytarılmamalıdır","tr":"Emanet geri verilmemelidir","ru":"Доверенное не возвращают","en":"Trusts should not be returned","ar":"لا تُرد الأمانات"},{"az":"Salam qadağandır","tr":"Selam yasaktır","ru":"Приветствие запрещено","en":"Greeting is forbidden","ar":"التحية ممنوعة"}],"correct":0,"explanation":{"az":"Ayə dində məcburiyyət olmadığını bildirir.","tr":"Ayet dinde zorlama olmadığını bildirir.","ru":"Аят утверждает отсутствие принуждения в религии.","en":"The verse states that there is no compulsion in religion.","ar":"تقرر الآية أنه لا إكراه في الدين."},"source_reference":"Quran 2:256","source_url":"https://quran.com/2/256","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"general-03","option_ids":["general-03:0","general-03:1","general-03:2","general-03:3"],"correct_option_id":"general-03:0","review_status":"legacy-reviewed"}'::jsonb where id='general-03';
update shams_private.quiz_bank set payload='{"id":"general-04","category":"general","difficulty":2,"question":{"az":"Nisa surəsinin 135-ci ayəsinə görə insan öz əleyhinə olsa belə nəyə sadiq qalmalıdır?","tr":"Kur’an kişinin kendi aleyhine olsa da neye bağlı kalmasını öğretir?","ru":"Чему Коран учит следовать даже против собственных интересов?","en":"What does the Quran teach upholding even against oneself?","ar":"ماذا يأمر القرآن بإقامته ولو على النفس؟"},"options":[{"az":"Qərəzə","tr":"Önyargıya","ru":"Предвзятости","en":"Bias","ar":"التحيز"},{"az":"Yalana","tr":"Yalana","ru":"Лжи","en":"Falsehood","ar":"الكذب"},{"az":"Təkəbbürə","tr":"Kibre","ru":"Высокомерию","en":"Arrogance","ar":"الكبر"},{"az":"Ədalətə","tr":"Adalete","ru":"Справедливости","en":"Justice","ar":"العدل"}],"correct":3,"explanation":{"az":"Nisa 4:135 hətta özünə qarşı olsa belə ədalətli şahidliyi vurğulayır.","tr":"Nisa 4:135 kendi aleyhine de olsa adil şahitliği vurgular.","ru":"Ан-Ниса 4:135 подчёркивает справедливое свидетельство даже против себя.","en":"An-Nisa 4:135 stresses just testimony even against oneself.","ar":"تؤكد النساء ٤:١٣٥ الشهادة بالعدل ولو على النفس."},"source_reference":"Quran 4:135","source_url":"https://quran.com/4/135","reviewed":true,"active":true,"topic":"general","tier":2,"concept_id":"general-04","option_ids":["general-04:0","general-04:1","general-04:2","general-04:3"],"correct_option_id":"general-04:3","review_status":"legacy-reviewed"}'::jsonb where id='general-04';
update shams_private.quiz_bank set payload='{"id":"general-05","category":"general","difficulty":1,"question":{"az":"Hucurat surəsinin 13-cü ayəsinə görə insanların xalqlara və qəbilələrə ayrılmasının məqsədi nədir?","tr":"Kur’an’a göre halklara ve kabilelere ayrılmanın amaçlarından biri nedir?","ru":"Какова одна из целей различия народов и племён по Корану?","en":"According to the Quran, what is one purpose of peoples and tribes?","ar":"ما إحدى غايات جعل الناس شعوباً وقبائل في القرآن؟"},"options":[{"az":"Daim savaşmaq","tr":"Daima savaşmak","ru":"Постоянно воевать","en":"Endless fighting","ar":"القتال الدائم"},{"az":"Ədalətdən qaçmaq","tr":"Adaletten kaçmak","ru":"Избегать справедливости","en":"Avoiding justice","ar":"تجنب العدل"},{"az":"Bir-birini tanımaq","tr":"Birbirini tanımak","ru":"Познавать друг друга","en":"Knowing one another","ar":"التعارف"},{"az":"Bir-birini alçaltmaq","tr":"Birbirini küçümsemek","ru":"Унижать друг друга","en":"Belittling one another","ar":"تحقير بعضهم بعضاً"}],"correct":2,"explanation":{"az":"Hucurat 49:13 tanışlığı və təqvanı önə çəkir.","tr":"Hucurat 49:13 tanışmayı ve takvayı öne çıkarır.","ru":"Аль-Худжурат 49:13 подчёркивает взаимное познание и богобоязненность.","en":"Al-Hujurat 49:13 highlights mutual knowledge and taqwa.","ar":"تبرز الحجرات ٤٩:١٣ التعارف والتقوى."},"source_reference":"Quran 49:13","source_url":"https://quran.com/49/13","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"general-05","option_ids":["general-05:0","general-05:1","general-05:2","general-05:3"],"correct_option_id":"general-05:2","review_status":"legacy-reviewed"}'::jsonb where id='general-05';
update shams_private.quiz_bank set payload='{"id":"general-06","category":"general","difficulty":1,"question":{"az":"Tövbə surəsinin 60-cı ayəsində zəkat verilənlər arasında hansı qrup göstərilir?","tr":"Kur’an’da zekât alanlar arasında hangi grup açıkça anılır?","ru":"Какая группа прямо названа среди получателей закята?","en":"Which group is explicitly among the recipients of zakat?","ar":"أي فئة ذُكرت صراحة ضمن مستحقي الزكاة؟"},"options":[{"az":"Yalnız idmançılar","tr":"Yalnız sporcular","ru":"Только спортсмены","en":"Only athletes","ar":"الرياضيون فقط"},{"az":"Yoxsullar və ehtiyacı olanlar","tr":"Fakirler ve yoksullar","ru":"Бедные и нуждающиеся","en":"The poor and needy","ar":"الفقراء والمساكين"},{"az":"Yalnız varlı hökmdarlar","tr":"Yalnız zengin hükümdarlar","ru":"Только богатые правители","en":"Only wealthy rulers","ar":"الحكام الأغنياء فقط"},{"az":"Yalnız tacirlər","tr":"Yalnız tüccarlar","ru":"Только торговцы","en":"Only merchants","ar":"التجار فقط"}],"correct":1,"explanation":{"az":"Tövbə 9:60 yoxsulları və miskinləri siyahıya daxil edir.","tr":"Tevbe 9:60 fakirleri ve yoksulları listeye alır.","ru":"Ат-Тауба 9:60 включает бедных и нуждающихся.","en":"At-Tawbah 9:60 includes the poor and needy.","ar":"تُدرج التوبة ٩:٦٠ الفقراء والمساكين."},"source_reference":"Quran 9:60","source_url":"https://quran.com/9/60","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"general-06","option_ids":["general-06:0","general-06:1","general-06:2","general-06:3"],"correct_option_id":"general-06:1","review_status":"legacy-reviewed"}'::jsonb where id='general-06';
update shams_private.quiz_bank set payload='{"id":"general-07","category":"general","difficulty":2,"question":{"az":"İnfitar surəsinin 10–12-ci ayələrində əməlləri yazanlar necə təqdim olunur?","tr":"İnfitar 82:10–12’de amelleri kaydedenler nasıl tanıtılır?","ru":"Как в Аль-Инфитар 82:10–12 представлены записывающие дела?","en":"How are the recorders of deeds described in Al-Infitar 82:10–12?","ar":"كيف تصف الانفطار ٨٢:١٠–١٢ كاتبي الأعمال؟"},"options":[{"az":"Şərəfli yazan mələklər","tr":"Değerli yazıcı melekler","ru":"Благородные ангелы-писцы","en":"Honourable recording angels","ar":"ملائكة كرام كاتبون"},{"az":"Tacirlər","tr":"Tüccarlar","ru":"Торговцы","en":"Merchants","ar":"تجار"},{"az":"Dənizçilər","tr":"Denizciler","ru":"Моряки","en":"Sailors","ar":"بحارة"},{"az":"Ustalar","tr":"Ustalar","ru":"Мастера","en":"Craftspeople","ar":"صنّاع"}],"correct":0,"explanation":{"az":"Ayələr əməlləri bilən şərəfli yazanlardan danışır.","tr":"Ayetler amelleri bilen değerli yazıcılardan söz eder.","ru":"Аяты говорят о благородных писцах, знающих дела.","en":"The verses speak of honourable recorders who know people’s deeds.","ar":"تذكر الآيات كراماً كاتبين يعلمون الأعمال."},"source_reference":"Quran 82:10-12","source_url":"https://quran.com/82/10-12","reviewed":true,"active":true,"topic":"general","tier":2,"concept_id":"general-07","option_ids":["general-07:0","general-07:1","general-07:2","general-07:3"],"correct_option_id":"general-07:0","review_status":"legacy-reviewed"}'::jsonb where id='general-07';
update shams_private.quiz_bank set payload='{"id":"general-08","category":"general","difficulty":1,"question":{"az":"Bəqərə surəsinin 97-ci ayəsinə görə Quranı Peyğəmbərin qəlbinə hansı mələk endirib?","tr":"Kur’an’ı Peygamber’in kalbine indirmekle hangi melek ilişkilendirilir?","ru":"Какой ангел связан с ниспосланием Корана в сердце Пророка?","en":"Which angel is associated with bringing the Quran to the Prophet’s heart?","ar":"أي مَلَك ارتبط بإنزال القرآن على قلب النبي؟"},"options":[{"az":"Mikail","tr":"Mikail","ru":"Микаиль","en":"Mikail","ar":"ميكائيل"},{"az":"Malik","tr":"Malik","ru":"Малик","en":"Malik","ar":"مالك"},{"az":"Harut","tr":"Harut","ru":"Харут","en":"Harut","ar":"هاروت"},{"az":"Cəbrail","tr":"Cebrail","ru":"Джибриль","en":"Jibril (Gabriel)","ar":"جبريل"}],"correct":3,"explanation":{"az":"Bəqərə 2:97-də Cəbrailin adı açıq çəkilir.","tr":"Bakara 2:97’de Cebrail’in adı açıkça anılır.","ru":"Аль-Бакара 2:97 прямо называет Джибриля.","en":"Al-Baqarah 2:97 explicitly names Jibril.","ar":"تذكر البقرة ٢:٩٧ جبريل بالاسم."},"source_reference":"Quran 2:97","source_url":"https://quran.com/2/97","reviewed":true,"active":true,"topic":"general","tier":1,"concept_id":"general-08","option_ids":["general-08:0","general-08:1","general-08:2","general-08:3"],"correct_option_id":"general-08:3","review_status":"legacy-reviewed"}'::jsonb where id='general-08';
update shams_private.quiz_bank set payload='{"id":"general-09","category":"general","difficulty":3,"question":{"az":"Bəqərə surəsinin 185-ci ayəsində Quran kimlər üçün hidayət kimi təqdim olunur?","tr":"Bakara 2:185 Kur’an’ı kimler için rehber olarak tanıtır?","ru":"Для кого Аль-Бакара 2:185 описывает Коран как руководство?","en":"For whom does Al-Baqarah 2:185 describe the Quran as guidance?","ar":"لمن تصف البقرة ٢:١٨٥ القرآن بأنه هدى؟"},"options":[{"az":"Yalnız bir peşə üçün","tr":"Yalnız bir meslek için","ru":"Только для одной профессии","en":"Only for one profession","ar":"لمهنة واحدة فقط"},{"az":"Yalnız bir şəhər üçün","tr":"Yalnız bir şehir için","ru":"Только для одного города","en":"Only for one city","ar":"لمدينة واحدة فقط"},{"az":"İnsanlar üçün","tr":"İnsanlar için","ru":"Для людей","en":"For humanity","ar":"للناس"},{"az":"Yalnız hökmdarlar üçün","tr":"Yalnız hükümdarlar için","ru":"Только для правителей","en":"Only for rulers","ar":"للحكام فقط"}],"correct":2,"explanation":{"az":"Ayədə Quran insanlara yol göstərən kitab kimi təsvir olunur.","tr":"Ayette Kur’an insanlara yol gösteren kitap olarak anlatılır.","ru":"Аят описывает Коран как руководство для людей.","en":"The verse describes the Quran as guidance for people.","ar":"تصف الآية القرآن بأنه هدى للناس."},"source_reference":"Quran 2:185","source_url":"https://quran.com/2/185","reviewed":true,"active":true,"topic":"general","tier":3,"concept_id":"general-09","option_ids":["general-09:0","general-09:1","general-09:2","general-09:3"],"correct_option_id":"general-09:2","review_status":"legacy-reviewed"}'::jsonb where id='general-09';
update shams_private.quiz_bank set payload='{"id":"general-10","category":"general","difficulty":4,"question":{"az":"Ali-İmran surəsinin 185-ci ayəsinə görə hər bir canlı nəyi dadacaq?","tr":"Âl-i İmran 3:185’te her nefsin neyi tadacağı bildirilir?","ru":"Что, согласно Аль-Имран 3:185, вкусит каждая душа?","en":"What will every soul taste according to Ali Imran 3:185?","ar":"ماذا تذوق كل نفس بحسب آل عمران ٣:١٨٥؟"},"options":[{"az":"Bütün peşələri","tr":"Bütün meslekleri","ru":"Все профессии","en":"Every profession","ar":"كل المهن"},{"az":"Ölümü","tr":"Ölümü","ru":"Смерть","en":"Death","ar":"الموت"},{"az":"Hökmdarlığı","tr":"Hükümdarlığı","ru":"Власть","en":"Kingship","ar":"الملك"},{"az":"Bütün sərvətləri","tr":"Bütün servetleri","ru":"Все богатства","en":"Every fortune","ar":"كل الثروات"}],"correct":1,"explanation":{"az":"Ayə ölümün hər nəfsə aid olduğunu xatırladır.","tr":"Ayet ölümün her nefse ait olduğunu hatırlatır.","ru":"Аят напоминает о смерти каждой души.","en":"The verse reminds us that every soul will taste death.","ar":"تذكر الآية أن كل نفس ذائقة الموت."},"source_reference":"Quran 3:185","source_url":"https://quran.com/3/185","reviewed":true,"active":true,"topic":"general","tier":3,"concept_id":"general-10","option_ids":["general-10:0","general-10:1","general-10:2","general-10:3"],"correct_option_id":"general-10:1","review_status":"legacy-reviewed"}'::jsonb where id='general-10';
